quests[12568] = { id = 12568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Done to Death", description = "Trust me, {race}. I know....\n\nThe smell of burnt flesh has become sickening to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren never walk with the Scourge.\n\nPour this oil on the corpses of our fallen to ensure that we never face them on the battlefield as enemies.", sourceObjective = "Captain Rupert wants you to use the Incinerating Oil on 5 Defeated Argent Footmen in Drak'Sotra.", completion = "Thank you, {name}.\n\nIt's not the most glorious job on the battlefield, but it must be done. I'll make note of your service in my report.\n\nCaptain Grondel is likely waiting for you to the northeast, just outside the amphitheater.", sourceObjectiveStatus = "unverified-source-field" }
quests[12569] = { id = 12569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Mastery: The Ambush", description = "The largest crocolisk in the basin, known around here as \"Bushwhacker\" for his ambush prowess, likes to sun himself in the shallow waters of River's Heart. It's the large lake at the basin's center, and is to the east of our camp.\n\nI want you to take the camouflage I've prepared and hide on the western beach of River's Heart and ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to overcome him.", sourceObjective = "Bring Bushwhacker's Jaw to Debaar at the Nesingwary Base Camp.", progress = "Did our plan work?", completion = "<Debaar listens as you describe the failure of the disguise.>\n\nWhat do you mean, our plan didn't work as intended?\n\nWell, you did manage to get the kill, to your credit. Look at the size of this jaw! Hemet will be proud of our efforts. This crocolisk was truly a monster.", sourceObjectiveStatus = "unverified-source-field" }
quests[12570] = { id = 12570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortunate Misunderstandings", description = "I sorry! I not mean to get you in trouble!\n\n<The injured oracle stares at you blankly for a long while.>\n\nYou save me! We thank you. We going to go back to village now. You come too... you can stay with us! Puppy-men kind of mean anyway.\n\nLet me know when you ready to go, okay?", sourceObjective = "Escort the Injured Rainspeaker Oracle to Rainspeaker Canopy and speak to High-Oracle Soo-say.", progress = "Who you? You stink of puppy-men.", completion = "You help us? You welcome then, dryskin.", sourceObjectiveStatus = "unverified-source-field" }
quests[12571] = { id = 12571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make the Bad Snake Go Away", description = "We were here long before the puppy-men came. This is very sacred place - we will not leave.\n\nYou seem like maybe you good, but we have Lafoo stay with you just in case. You understand we think.\n\nThere snakes thing that keeps trying to eat our hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to northeast.", sourceObjective = "High-Oracle Soo-say in Rainspeaker Canopy wants you to kill Venomtip and 10 Emperor Cobras.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "<High-Oracle Soo-say seems to stare right through you.>", completion = "Snake gone?\n\nGood {race}. We thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12572] = { id = 12572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gods like Shiny Things", description = "Soo-say said we go with you. You be nice, okay?\n\nOoh, ooh! We know! We can make Soo-say happy if we bring back more offerings for shrine! We not need to go far, there's always stuffs to dig up around village... just look for sparkles in dirt!\n\nLet's go! Let's go! More offerings for shrine!", sourceObjective = "Collect 6 of the treasures that Lafoo digs up and bring them to High-Oracle Soo-say in Rainspeaker Canopy.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Hello dryskin. You get along with Lafoo good?", completion = "Shinies for the Great Rain Stone! Good! Good!\n\nWe offer these right away. Lafoo thought of this, yes? He a very smart Rainspeaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[12573] = { id = 12573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Peace", description = "We have great idea. You were friends with puppy-men, they maybe listen to you.\n\nWe want you to go give offering to Shaman Vekjik. He southwest where river turns into waterfall.  Tell puppy-man we no want fight. Tell him we play nice.\n\nYou good {race}. We trust you do this right.", sourceObjective = "High-Oracle Soo-say at Rainspeaker Canopy wants you to give a peace offering to Shaman Vekjik and then return with his response.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Puppy-men play nice now?", completion = "So mean! We only be nice and they only be mean.\n\nThey keep messing with great stones... maybe they not know great stones are sacred.", sourceObjectiveStatus = "unverified-source-field" }
quests[12574] = { id = 12574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back So Soon?", description = "<High-Oracle Soo-say stares at your forehead for a while before speaking.>\n\nSoo-gan ask for help. We think they might have been attacked by puppy-men again.\n\nWe sending you and Jaloot to help... follow west river up to Mistwhisper Refuge. Do what Soo-gan says... hit the puppy-men on the nose if they being mean, they don't like that.\n\n<High-Oracle Soo-say goes back to staring at your forehead as you leave.>", sourceObjective = "Travel to Mistwhisper Refuge and speak to Mistcaller Soo-gan.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", completion = "We think we seen you before. You visit Mistwhisper village sometime already?\n\nSoo-say said you good. Soo-say smart, so we trust you too.\n\n<Mistcaller Soo-gan offers an awkwardly large smile.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12575] = { id = 12575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Mistwhisper Treasure", description = "So some puppy-men come and smash blue crystals at Great Mist Stone! Lots of rain and lightning and badness... blue is wrong crystal for Great Mist Stone! Dumb puppy-men.\n\nAfter lightning, puppy-men stole big treasure we found in the sea-lake. We need treasure back to give to Great Mist Stone! Mist Stone is angry after what the puppy-men did!\n\nOne who took it named Tarter... no, Tiktak... no, no... Tartek. That it, Tartek! He went to the camp thing to north. Go get treasure back!", sourceObjective = "Kill Warlord Tartek and retrieve the Mistwhisper Treasure for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Dumb puppy-thieves.", completion = "You did it! You strong and nice! Good friend of Mistwhispers!\n\n<Mistcaller Soo-gan lets loose a big toothy grin.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12576] = { id = 12576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forced Hand", description = "We try to be nice to puppy-men ever since they came, but they nothing but mean.\n\nWe okay with them being dumb - they not do much harm. Now they mess with sacred shrines though. Sacred shrines not for messing with. The Great Stones are here from all the way back when the Great Ones made us.\n\nWe wouldn't know what to do if the Great Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!", sourceObjective = "Kill 8 Frenzyheart Spearbearers and 6 Frenzyheart Scavengers for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "They always want fight! We no want fight, but we need to protect sacred stuffs.", completion = "You squash good. Thank you for help.", sourceObjectiveStatus = "unverified-source-field" }
quests[12577] = { id = 12577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Time!", description = "You're a good dryskin. Mistwhisper safe, treasure safe, and puppy-men sure to leave us alone now.\n\nYou go back to Rainspeaker Canopy and tell Soo-say you done good.", sourceObjective = "Return to Rainspeaker Canopy.", completion = "You back so soon!\n\nWent good then, yeah?", sourceObjectiveStatus = "unverified-source-field" }
quests[12578] = { id = 12578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Angry Gorloc", description = "I not think you be back in time to go out again, but I wrong. I sending Moodle to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their village is east, up ridge, northeast of broken pillar.\n\nYou go with Moodle! He extra smart Rainspeaker... you listen to him good-like.", sourceObjective = "Travel to Mosswalker Village and speak to Moodle once you've arrived.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Soo-say fumbles a bit, but he's not dumb. I do think he's been far too forgiving though... the puppy-men are not going to stop or leave us alone. The only way to stop them is to kill them... there is no \"peace.\"\n\n<Moodle puffs up his chest and points to himself.>\n\nThat I am good at.", completion = "Before you say anything, do not assume me as foolish as most of the Oracles you've met. I've been into the world a bit, I've learned your language, and I'm not easily duped.\n\nI knew the Mosswalkers were dead before we ever came, though I didn't know that the undead were behind it.\n\nThey are not supposed to be able to enter this land... the destruction of the Lifeblood Pillar must have allowed them in somehow. We must see to it that they leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[12579] = { id = 12579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifeblood of the Mosswalker Shrine", description = "I've always suspected that the pillars have been the main reason for our weather and seclusion from the undead... this confirms it a bit.\n\nNot terribly long ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather changed for the mosswalkers almost immediately... it began to snow, something we never see.\n\nThey were able to stop the snow by bringing more lifeblood crystals to the Great Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.", sourceObjective = "Moodle wants you to collect 10 Lifeblood Shards, but stay away from the cave inside of the pillar itself.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "The Mosswalkers were good people... they did not deserve this.", completion = "We might be too late for the shards to make a difference, but our options are somewhat limited.", sourceObjectiveStatus = "unverified-source-field" }
quests[12580] = { id = 12580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosswalker Savior", description = "There's some small chance that the Mosswalkers are not all dead yet... and at the very least, they deserve to not be butchered like this.\n\nLet's find some revenge for this slaughter and see if there are any to be saved in the process.", sourceObjective = "Moodle wants you to rescue 6 of the Mosswalker Victims in Mosswalker Village, though some of them may no longer be alive to save.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "I wish I had known how key the pillars and the stones were much earlier... perhaps I could have prevented this.", completion = "I'm very glad there were some to be saved... with luck, they'll make it back to Rainspeaker Canopy safely.", sourceObjectiveStatus = "unverified-source-field" }
quests[12581] = { id = 12581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Burden", description = "Perhaps the crystals will ward off the undead gradually, but there is one more thing that must be done.\n\nWe need to find the leader of these undead and kill him to ensure there's no one to push the wretches back upon us. If my suspicions are correct, he will be somewhere inside the fallen pillar... the Sundered Shard.\n\nThe corpses being dragged there would suggest as much anyway.\n\nI'll place the shards and bring the news to Soo-say... I'll leave the rest up to you.", sourceObjective = "Kill Artruis the Heartless.\n\nMoodle will not be able to accompany you on this task.", progress = "<The phylactery rests ominously on the ground next to Artruis's dead form.>", completion = "<Inside Artruis's Phylactery you see what seems like an endless void... and you think you hear screaming in the distance from somewhere inside.>\n\n<As you're about to leave, you see an object floating in the void, just barely in reach.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12582] = { id = 12582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzyheart Champion", sourceObjective = "I know you weren't traitor thing like others said. We hunt together... I know you better than all of them. Thank you for saving me.\n\nMay sound funny... I not a big fan of big-tongues... but even I feel little bad for big-tongue dying like that though...they fight good enough they deserve fair fight.\n\nYou want to be friends with Frenzyheart again? I think I can convince them that you save me and got the big-tongues good. I no want you to make me look dumb though, so you sure no more big-tongues for you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12583] = { id = 12583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crashed Sprayer", description = "I know that one of those plague sprayers crashed somewhere within Drak'Sotra to the west of us.\n\nWhy don't you see if you can find it. I can use the parts from the sprayer to create the device that's going to bring those things down!", sourceObjective = "Specialist Cogwheel at Drak'Sotra has asked you to collect Plague Sprayer Parts.", progress = "Do you have the parts? Huh? Do you?", completion = "<The specialist steps back a bit when presented with the parts.>\n\nEw, those things are totally gross!\n\nOkay, okay, hand them over and I'll see what I can do. I probably should have had you take them to a priest first for purification.", sourceObjectiveStatus = "unverified-source-field" }
quests[12584] = { id = 12584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pure Evil", description = "We know that Kolramas, the crashed necropolis to the southeast, was carrying a large amount of an ore known as saronite when the trolls shot it down.\n\nMy scouts tell me that much of the saronite is strewn about within the innards of that thing.\n\nEitrigg and his friends back at The Argent Stand want a bunch of the stuff so that they can study it.\n\nI want you to head in there and see if you can collect enough for them.", sourceObjective = "Captain Rupert has asked you to collect 10 Chunks of Saronite and deliver them to Eitrigg at The Argent Stand.", progress = "Yes, {class}?\n\nPlease tell me that you have the saronite that we requested Captain Rupert to acquire?", completion = "Can you not feel the pure evil of the stuff?\n\nWe must use the expertise and magics at our disposal, combined with the power of the Holy Light, to pierce the veil of iniquity surrounding this tainted ore. We must determine its origins.\n\nQuickly, hand the saronite to me!", sourceObjectiveStatus = "unverified-source-field" }
quests[12585] = { id = 12585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", sourceObjective = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", progress = "Ya got the wood fer a fire, {race}?", completion = "Mighty kind of ya, {name}. Mighty kind indeed.\n\nNow you'll be findin' Cap'n Arnath due west o' here, just over the rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12586] = { id = 12586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bigger Game", description = "Well, {name}, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.\n\nBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.\n\nI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.", sourceObjective = "Talk to <x> at <x>.", sourceObjectiveStatus = "unverified-source-field" }
quests[12587] = { id = 12587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", sourceObjective = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'valok.", completion = "Well, {name}, at least you've made it back in one piece. I suppose that's worth something....", sourceObjectiveStatus = "unverified-source-field" }
quests[12588] = { id = 12588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Can You Dig It?", description = "One of our troops came across an old treasure map during our last offensive. If what it shows is true, then there are priceless troll artifacts nearby.\n\nMy soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you to follow up on this intelligence.\n\nTake this shovel and use it at the loose dirt mounds to the southwest. Return to me after a diligent search has been conducted.", sourceObjective = "Captain Brandon in Drak'Sotra wants you to use the Steel Spade on the nearby Ancient Dirt Mounds to recover the Ancient Drakkari Relic.", completion = "Thank you for looking into this for me, {name}. I'll make mention of your service in my report.\n\nYou'll likely want to visit Captain Rupert next. He's stationed at the wall due east of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12589] = { id = 12589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick, What Kick?", description = "So you think you can shoot?\n\nWell, let's give it a try. Here, we'll start you out with something nice and gentle. Don't worry, it's got no kick to it at all. Remember, don't point that gun at anything you don't intend to fire at.\n\nNow, when you're ready, just take aim at that apple on top o' old Lucky Wilhelm's head and let 'er fly!", sourceObjective = "Using the RJR Rifle, shoot the apple on top of Lucky Wilhelm's head, then speak with Drostan.", progress = "Satisfied with the results?", completion = "You're not a bad shot, but you'll get better with practice. How would you like to make a little wager?", sourceObjectiveStatus = "unverified-source-field" }
quests[12591] = { id = 12591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two nethurbian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", sourceObjective = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters.", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12592] = { id = 12592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Hunter's Challenge", description = "So y'have something of a hunter's instinct. You're not a bad shot, and Hemet hasn't driven you out, so he must be planning on including you in the hunt.\n\nHow'd you like to have a bit of a competition, just me and you?\n\nHemet and the others will ask you to help in their hunting. Along the way, you and I will count up the kills we contribute to their goals. Now, this isn't something you can win in the blink of an eye, and you'll find yourself killing many different kinds of creatures. Good luck!", sourceObjective = "Kill 60 Game Animals while you aid Hemet and his companions in their hunting. When you've killed your 60, return to Drostan at the Nesingwary Base Camp to compare numbers.", progress = "Care to count 'em up?", completion = "So, you've come to concede already?\n\n<Drostan's jaw drops as you tell him you've already made all your kills.>\n\nNo way! How in Azeroth did you do that? I just made my 58th. So close!\n\nBut fair's fair. I underestimated you, {name}, but you've earned this victory fair and square.", sourceObjectiveStatus = "unverified-source-field" }
quests[12593] = { id = 12593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service Of The Lich King", description = "All that I am: anger, cruelty, vengeance - I bestow upon you, my chosen knight. I have granted you immortality so that you may herald in a new, dark age for the Scourge.\n\nGaze now upon the lands below us. The Scarlet Crusade scurries to undo my work, while Light's Hope stands defiantly against us - a blemish upon these Plaguelands. They must all be shown the price of their defiance.\n\nYou will become my force of retribution. Where you tread, doom will follow. Go now and claim your destiny, death knight.", sourceObjective = "Report to Instructor Razuvious in the Heart of Acherus.", completion = "You have heard the call of the Lich King, {class}. Now is the time to answer your master.", sourceObjectiveStatus = "unverified-source-field" }
quests[12594] = { id = 12594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Couldn't Care Less", description = "Of all the posts, they throw me in this one.\n\nThe place is flooded with putrid, stagnant water and now it's host to sewage elementals!\n\nI don't really know what they are or why they're here, and frankly I couldn't care less. What I do know is they're making a mess of my sector! How am I supposed to conduct any dignified military operations with those foul things roaming around?\n\nGet out there, {class}, and don't come back 'til you've cleared your share of 'em off of my battlefield!", sourceObjective = "Captain Grondel wants you to kill 7 Mossy Rampagers in Drak'Agal.", progress = "You clear the area of bog beasts yet, {class}?", completion = "You sure about that, {race}?\n\nSeems to me like there are more of them things out there now than when you started!", sourceObjectiveStatus = "unverified-source-field" }
quests[12595] = { id = 12595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bigger Game", description = "Well, {name}, you've certainly proven your mettle as a hunter of all kinds of game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these creatures are sufficient to test their hunting skills, but others, like myself, crave larger challenges.\n\nDorian Drakestalker went north, across Bittertide Lake and established a camp there. He's heard rumors of gigantic primordial drakes. Just imagine what a quarry they would be! Go check up on Dorian and see if he's had any luck.", sourceObjective = "Speak with Dorian Drakestalker at Dorian's Outpost in Sholazar Basin.", completion = "So old Hemet didn't forget about me, after all. I suppose he's going to want to participate in the hunt once we've done all the hard work. Don't worry, there are plenty of drakes to go around. Hemet will get his wish.", sourceObjectiveStatus = "unverified-source-field" }
quests[12596] = { id = 12596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pa'Troll", description = "Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can call me... Commander.\n\nDon't think you're going to just cruise through my region, picking which missions you're going to participate in, answering to no one.\n\nHere, you report to me and you follow my orders to the letter. Understood?!\n\nFirst, you're going to get familiar with my men and the region we're charged with clearing.\n\nReport to each of them and do as they ask. Return to me when your patrol is done.", sourceObjective = "Commander Kunz at The Argent Stand wants you to visit the four Argent Crusade posts, follow their leaders' orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Southeast of here.\n\nCaptain Grondel is posted in Drak'Agal, due east.\n\nAlchemist Finklestein is posted in Heb'Valok, to the north.", completion = "It's about time you got your carcass back here! Thought we'd lost ya to the Scourge - not that it would've been a great loss....\n\nIf you're going to continue to serve the Crusade, you'd best make a more impressive showing.\n\nTake note, {race}! Your future patrols will be rewarded based on your timeliness.\n\nDismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[12597] = { id = 12597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something for the Pain", description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", sourceObjective = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.", progress = "Have you collected the water-poppies, {name}?", completion = "Fine specimens, {name}.\n\nOn behalf of my soldiers, I thank you for your efforts today.\n\nCaptain Rupert is likely the next stop on your patrol. He's stationed at the wall just east of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12598] = { id = 12598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two Nerubian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", sourceObjective = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nerubian Craters.", progress = "Have you sealed the nerubian tunnels, {name}?", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12599] = { id = 12599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", sourceObjective = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", progress = "Ya got the wood fer a fire, {race}?", completion = "Mighty kind of ya, {name}. Mighty kind indeed.\n\nNow you'll be findin' ol' Finklestein due west o' here, just over the rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12601] = { id = 12601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", sourceObjective = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", sourceObjectiveStatus = "unverified-source-field" }
quests[12602] = { id = 12602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", sourceObjective = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", sourceObjectiveStatus = "unverified-source-field" }
quests[12603] = { id = 12603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharpening Your Talons", description = "The primordial drakes occupy most of the area to the north and east, and I can feel the heat of their breath even at this distance. Before we can challenge the mightiest among the drakes, we must test our skills against the lesser creatures.\n\nStill, don't let your guard down; any one of these beasts can devour a man whole. Once you've familiarized yourself with the combat tactics of these drakes, return and I will tell you our next step.", sourceObjective = "Kill 6 Primordial Drakes and then speak with Dorian Drakestalker at Dorian's Outpost.", progress = "Have you tested your skills?", completion = "I can hear the confidence in your words. Good, the experience will come in handy when we face the queen of the drakes.", sourceObjectiveStatus = "unverified-source-field" }
quests[12604] = { id = 12604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Congratulations!", sourceObjective = "You made excellent time on that patrol. It appears that you may be of use to us after all.\n\nAs promised, here's a little something extra for your efforts.\n\nKeep up the good work, {name}.\n\nDismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[12605] = { id = 12605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Bait", description = "We're not likely to get Broodmother Slivina's attention waving our arms around like fools, but if we're smart, we can bait her into fighting us. We'll also secure more, uh, fodder for my little project.\n\n<Dorian glances over at Zootfizzle.>\n\nBut don't worry about that for now. Just look for the primordial drake eggs in the area east and northeast of the camp. Burst them open and scoop up the hatchlings that come out. When the broodmother realizes what we've done, she'll have no choice but to face us.", sourceObjective = "Bring 6 Primordial Hatchlings to Dorian Drakestalker at Dorian's Outpost.", progress = "Have you secured the bait we'll need to get the broodmother's attention?", completion = "Ah, well done. Plenty of little hatchlings for Zootfizzle over there!", sourceObjectiveStatus = "unverified-source-field" }
quests[12606] = { id = 12606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cocooned!", description = "Now that the tunnels have been sealed, our next concern is recovering those who have fallen to the enemy.\n\nWith any luck, several of our soldiers are still alive and relatively well inside the nerubian cocoons.\n\nFree them, {class}, while you still can!", sourceObjective = "Captain Rupert wants you to open the Nerubian Cocoons in Drak'Sotra and return to him once you have freed 3 Captive Footmen.", completion = "These nerubians have taken a heavy toll, {class}.\n\nNevertheless, I am grateful for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[12607] = { id = 12607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mammoth Undertaking", description = "Before you go off challenging Broodmother Slivina, Dorian thought it might be a good idea for you and Hemet to coordinate your efforts by riding into battle on the back of a mammoth.\n\nThe area around the camp is full of them. Just take this bridle and slip it over the head of a shattertusk mammoth. Be careful of the bulls, though. They won't tolerate the harness at all. Bring the mammoth back here when you've found a suitable one.", sourceObjective = "Bring a Shattertusk Mammoth to Zootfizzle at Dorian's Outpost.", progress = "Everything taken care of?", completion = "Perfect! Now, all we need to do is get Hemet a stepladder...", sourceObjectiveStatus = "unverified-source-field" }
quests[12608] = { id = 12608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultist Incursion", description = "<It appears the Avatar of Freya was right.  The undead were not able to enter Sholazar Basin before the Lifeblood Pillar was brought down -- they used their living agents from the Cult of the Damned instead.>\n\n<You'd best warn her about the Lich King's living agents within Sholazar Basin.>", sourceObjective = "Speak to the Avatar of Freya at the Rainspeaker Rapids.", completion = "The living... willingly serve the Lich King?\n\nAll this time I've been searching for the wrong enemy, {race}.  Let us make haste and uproot these cultists from these lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[12609] = { id = 12609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking the Shelves", description = "Listen, {class}. I realize that it's a lot to ask....\n\nFresh spider ichor is somewhat hard to come by, even in these heavily infested regions. But Finklestein said he'd settle for no less than a vat of it, and that he needs it soon.\n\nI'll keep my men out in the field collecting reagents, but if the alchemist's order is going to be filled in time, they'll require some assistance.\n\nAs you roam the fields of Zul'Drak, keep your eyes peeled for trapdoor crawlers and bring me all of the ichor you can find.", sourceObjective = "Captain Arnath in Heb'Valok asked you to collect 7 units of Fresh Spider Ichor from the Trapdoor Crawlers in Zul'Drak.", progress = "Have you collected the reagents I need, {class}?", completion = "These look to be excellent samples, {name}.\n\nThank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12610] = { id = 12610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clipping Their Wings", description = "Ever since Finklestein's arrival, I've been relegated to collecting various ingredients for his experiments and recipes.\n\nI'll follow my orders as I've vowed to do, but I'm a seasoned veteran. I've taken part in dozens of conflicts. I'd much rather be on the front lines, having a more direct impact on the Crusade's outcome here.\n\nHelp me, {race}. Collect some bat wings for me so that I might get back to the real action sooner.", sourceObjective = "Captain Arnath in Heb'Valok has asked you to collect 7 Unblemished Bat Wings from Zul'Drak Bats.", progress = "Have you finished collecting those bat wings for Finklestein?", completion = "Excellent work, {name}.\n\nI thank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12611] = { id = 12611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returned Sevenfold", description = "The agents of the Lich King have foolishly trespassed upon these lands where the power of life rules supreme.  All harm they inflict will be returned to them sevenfold.\n\nThe monster directly responsible for corrupting the land is known as Thalgran Blightbringer; you will find him just to the north of here.  Take this ward and use it to reflect the power of death upon him.  Show the Scourge that the power of life prevails above all.", sourceObjective = "The Avatar of Freya wants you to defeat Thalgran Blightbringer by using Freya's Ward to reflect his Deathbolts back to him sevenfold.", progress = "Is it done, {name}?", completion = "You continue to prove yourself, {name}.  Perhaps I was too quick to judge you.\n\nI had assumed you were here with the poachers who were recently stranded in my lands, but perhaps you're ready to put that behind you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12612] = { id = 12612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Pillar", description = "The titans shaped entire life forms here, fostering their unfettered growth.\n\nThe five crystal pillars that surround the basin emanate pure lifeforce.  The Scourge should've never been able to penetrate the basin, but one of the pillars was destroyed.\n\nGo to the Lifeblood Pillar and see if you can find out what happened.  No undead would've been able to approach the pillar, so keep your eyes out for living intruders.  You'll find what remains of the pillar directly south of here.", sourceObjective = "Travel to the Lifeblood Pillar and look for clues to its destruction.", completion = "<The corpse is badly burnt.  There appear to be the remains of several powder kegs in the vicinity.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12613] = { id = 12613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Waygate - The Makers' Overlook", description = "We cannot stop now, {race}.  You've triggered the first switch, but one remains.\n\nThe titans constructed a second vantage point where they oversaw their creations.  You'll find it to the east, high in the mountains.\n\nPull the activation switch theta inside the overlook and the waygate will open.", sourceObjective = "The Avatar of Freya wants you to head to the Makers' Overlook in eastern Sholazar Basin and use the Activation Switch Theta.", progress = "Is it done, {name}?", completion = "The waygate is active, {name}.  It is time!", sourceObjectiveStatus = "unverified-source-field" }
quests[12614] = { id = 12614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Post-partum Aggression", description = "Broodmother Slivina's likely to be a snarling ball of teeth, spikes, and talons. You've gone and stolen her children away and no mother takes kindly to that.\n\n'Tis true they hatched from eggs, but she loves the little beasts no less than your mother loves you.\n\nShe'll be desperate and fierce in equal measures, everything Hemet loves in a target. You and he, along with that mammoth, should be a match for her.\n\nShe's on her perch at the northern edge of the Savage Thicket and hungers for revenge.", sourceObjective = "Kill Broodmother Slivina and return to Dorian Drakestalker at Dorian's Outpost.", progress = "Well, you're alive. How did you fare?", completion = "Well, I had a whole speech prepared, but the old man himself has some words he wants to say to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12615] = { id = 12615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Torga", description = "Hexxer Ubungo probably told you about making offerings to the gods of Zul'Drak. Zim'Abwa is not the only god that stands forgotten by the Drakkari.\n\nWe have taken refuge within the presence of Zim'Torga, the Mother of Prosperity. As with Zim'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you her blessing.", sourceObjective = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Torga.", progress = "<You can feel the eyes of the Mother of Prosperity upon you. She is wondering what a {race} such as yourself is doing standing before her.>", completion = "<Zim'Torga's thoughts pervade your own. She senses the offerings you are about give to her and is pleased.>\n\n<She conveys that you will be appropriately rewarded.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12616] = { id = 12616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chamber of Secrets", description = "Excellent, an experienced adventurer. Precisely what we need.\n\nThere has been talk from the Kirin Tor guarding Medivh's tower that something is amiss with Karazhan. There is a new power lurking within, one that answers neither to the Guardian's magic nor the Legion. From what they've scouted, it appears it is an elven prince called Tenris Mirkblood, and there is reason to believe he serves the Scourge.\n\nGo, my friend, investigate Mirkblood's chamber, and return with any information you might find.", sourceObjective = "The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant's Quarters of Karazhan.", completion = "The information you report is dire indeed if the orders you saw are legitimate. We can only hope that his mission was stopped early enough to prevent the enemy from knowing too much about our strengths.\n\nThank you, {name}. May you remain safe in these dark times.", sourceObjectiveStatus = "unverified-source-field" }
quests[12617] = { id = 12617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exterminate the Intruders", description = "I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge.\n\nI never anticipated the Lich King would send willing living servants to do his work.\n\nI could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, {name}.  Deliver my wrath to these insolent trespassers.", sourceObjective = "The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Death's Hand Encampment to the northwest and slay 8 Cultist Infiltrators.", progress = "Have you destroyed the trespassers, {name}?", completion = "You speak the truth.  The intruders at the camp were dealt with... but I'm afraid it might have been too late.", sourceObjectiveStatus = "unverified-source-field" }
quests[12618] = { id = 12618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Torga", progress = "<Zim'Torga looks on impassively. She wonders if you seek her continued blessing by presenting more Drakkari offerings to honor her.>", completion = "<The Mother of Prosperity beams her approval down upon you.>" }
quests[12619] = { id = 12619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emblazoned Runeblade", description = "The single most important piece of equipment to a death knight is the runeblade. It is through the runeblade that a death knight commands the powers of frost, blood and the unholy. The runeblade also acts as a vessel to store the death knight's runic power.\n\nThe time has come to create your first runeblade. Search the weapon racks on this floor and locate a battle-worn sword. Once found, take the sword to a nearby runeforge and use it to create a runeblade.", sourceObjective = "Search the weapon racks in Ebon Hold for a Battle-worn Sword and then use it on a runeforge to craft a Runebladed Sword.\n\nReturn the Runebladed Sword to Instructor Razuvious in Ebon Hold.", progress = "The runeblade is an extension of your being. A {class} cannot battle without a runeblade.", completion = "Well done, {name}. You have successfully created your first runebladed weapon. With it you will sow the seeds of chaos and destruction! In your wake will be a bloodied field of battle, littered with the corpses of all that would dare oppose the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12620] = { id = 12620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lifewarden's Wrath", description = "We were not quick enough, {name}.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them.\n\nWe don't have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.\n\nWe shall show this scum to not trifle with the titans' creations.", sourceObjective = "The Avatar of Freya at the Rainspeaker Rapids wants you to use Freya's Horn atop of the Glimmering Pillar.", progress = "Have you taken care of the cultists, {name}?", completion = "Impressive.  I wasn't expecting a mere mortal to prove as worthy an ally as you.\n\nI fear our efforts have not been sufficient, however.  The Scourge shows no signs of stopping.", sourceObjectiveStatus = "unverified-source-field" }
quests[12621] = { id = 12621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freya's Pact", description = "The cultists have been taken care of, but the Scourge's invasion has not slowed down.  The situation is becoming desperate, {name}.\n\nThere exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.", sourceObjective = "Listen to what the Avatar of Freya has to say.", progress = "We have little time.  The Scourge is preparing for a final push.", completion = "There is no turning back now.  If you agree to help me, you will do so without hesitation.", sourceObjectiveStatus = "unverified-source-field" }
quests[12622] = { id = 12622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leaders at Jin'Alai", description = "You thinkin' what Ahunae thinkin', mon?\n\nSome of the Drakkari trolls have gathered at the Pools of Jin'Alai to the southwest. We be needin' to draw out their leaders, and Ahunae knows just how you be doin' it, too!\n\nGo in there and kill those trolls. When you kill enough, their leaders show up.\n\nWhen they show up next to their totems, you make sure to be gettin' the treasure of Kutube'sa, Gawanil, and Chulo the Mad, mon.", sourceObjective = "Scalper Ahunae at Zim'Torga has asked you to retrieve the Treasure of Kutube'sa, the Treasure of Gawanil, and the Treasure of Chulo the Mad.", progress = "The {class} must be back talkin' to Ahunae because the {class} has all that treasure.", completion = "The scalper thinkin' that you be his kind of {race}!\n\nWhat's these candybars doin' in here? What we do with this, mon?\n\nAhunae say that you can have them back!", sourceObjectiveStatus = "unverified-source-field" }
quests[12623] = { id = 12623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Witch Doctor", description = "We Zandalari could use your help, {name}. We must put an end to what the Drakkari are doing to their gods!\n\nTo the northeast, up the great steps that lead to the next tier of Zul'Drak, lies Zim'Torga. It is the home to another of the god statues and a refuge that my people are desparately attempting to defend.\n\nI would like for you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is under constant attack from the Drakkari.", sourceObjective = "Speak with Witch Doctor Khufu at Zim'Torga.", completion = "Greetings to you, {class}. I am glad to hear that Ubungo found someone that he could trust.\n\nWelcome to Zim'Torga.", sourceObjectiveStatus = "unverified-source-field" }
quests[12624] = { id = 12624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Could Be Anywhere!", description = "When I found out that Miss Boulian was helping Nesingwary with his expedition, I signed up as a deckhand immediately.  You see, I'd been meaning to marry her for months!\n\nI had it all planned out.  I was going to propose the very night of the shipwreck... but now the ring is gone.  I've searched everywhere!\n\nI know it might sound crazy, but I know the engagement ring is in the Basin.  If some Venture Company didn't steal it, maybe a wild creature ate it.  But it's here somewhere... I just know it!", sourceObjective = "Look for a Golden Engagement Ring on the various creatures in Sholazar Basin.", progress = "The ring, {name}!  Please... tell me you've found it!", completion = "You did it!  You actually found it!\n\nI don't know... I don't know how to thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12625] = { id = 12625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominion Over Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold.\n\nThough your thoughts may still be hazy, we haven't a moment to spare. You must claim dominion over Acherus and your mind! The horns of war surge!\n\nTake the stairs on this floor - located north, south, east and west - to the garrison floor above us. Seek out Master Siegesmith Corvus and acquire his status report. It must be delivered to Thalanor.", sourceObjective = "Report to Master Siegesmith Corvus on the garrison floor of Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[12626] = { id = 12626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Company of the Damned", description = "<Corvus salutes.>\n\nOur stockpiles of weapons, armor and munitions are nearly at maximum capacity. We are ready for war!\n\n<Corvus rolls up a fleshy piece of vellum.>\n\nOn the other side of this garrison floor, southwest of here, you will find the officers' quarters. Take this status report there and deliver it to Scourge Commander Thalanor, battalion commander of the Company of the Damned.", sourceObjective = "Deliver Corvus' Report to Scourge Commander Thalanor at the garrison floor of Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[12627] = { id = 12627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through Jin'Alai", description = "I have been trying to commune with the gods. However, the medicine men at the Pools of Jin'Alai are performing rituals that are interfering with my attempts.\n\nIt is imperative that we break through their obtrusion. If you were to head southwest into the pools area, I am certain that you would come across the cauldrons they are using for their magic.\n\nDisturb each of the cauldrons to bring down their ritual that is blocking me.", sourceObjective = "Witch Doctor Khufu at Zim'Torga has asked you to disturb the Blue Cauldron, Green Cauldron, Purple Cauldron, and Red Cauldron.", completion = "Yes, I can already feel the difference. Thank you.\n\nLet us see if we can make contact with the gods now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12628] = { id = 12628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Speak With Har'koa", description = "The gods have spoken, {name}. We now know what you must do.\n\nYou must now go to the Altar of Har'koa to the southeast and speak with the leopard goddess.", sourceObjective = "Speak with Har'koa at the Altar of Har'koa.", completion = "Listen closely, little {race}. Time is of the essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[12629] = { id = 12629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can Run, But You Can't Hide", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the Reliquary of Agony. Slay abominations and gather the ghoul drool you'll find there then return to me with their remnants.", sourceObjective = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", progress = "Have you brought me the components I asked for, {name}?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do. Now brace yourself, {class}. This is where it gets good....", sourceObjectiveStatus = "unverified-source-field" }
quests[12630] = { id = 12630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kickin' Nass and Takin' Manes", description = "Before you meet Nass, there's something you should know.\n\nHe got a toxic dose of blight back in the day, and now he's deaf, blind, and mostly numb.\n\nIt's not all bad, though. He's virtually immune to the stuff now, which makes him perfect for certain tasks - like the one I'm about to give you.\n\nThere are many freshly scourged trolls nearby and we need to study the blight's effect on them. Take Nass, and this boot. When you've slain a troll, give him a good kick and he'll know to take a hair sample.", sourceObjective = "Stefan in Ebon Watch wants you to use Nass to collect 10 hair samples from Withered Trolls.\n\nIf you lose Nass, return to Stefan to recover him.", progress = "How's that boot holding up, {race}?", completion = "You know, you remind me an awful lot of my Nass.\n\nMaybe it's just the nose...", sourceObjectiveStatus = "unverified-source-field" }
quests[12631] = { id = 12631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invitation, of Sorts...", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", sourceObjective = "Take the Unliving Choker to Stefan at Ebon Watch.\n\nProvided item:", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, {name}, that you have been... chosen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12632] = { id = 12632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "But First My Offspring", description = "I am the last of the gods to be subdued, so we must first attempt to free the others. Bound by the magics of my subduers, I am unable to discern their fates.\n\nBut first, I would ask that you do me a kindness. Already the Drakkari turn my magic against me. They have transformed my offspring into monstrosities.\n\nTake one of my whiskers. Slay my tortured children and use the magic of it to release them from their nightmare, and bring them back to life.", sourceObjective = "Har'koa has asked you to use her whisker on the corpses of her children to free and resurrect them. Return to her at the Altar of Har'koa when you are done.", progress = "There are more of my offspring that you must free from their torment!", completion = "Thank you, {name}. I will never forget what you have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[12633] = { id = 12633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Calling", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", sourceObjective = "Take the Writhing Choker to Stefan in Ebon Watch.\n\nProvided item:", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, {name}, that you have been... chosen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12634] = { id = 12634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Make Lemonade, Some Make Liquor", description = "Life's tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won't sustain a thirsty expedition!\n\nWe need to get some booze cooking, and fast!!\n\nThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it's too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.", sourceObjective = "Bring 1 Orange, 2 Banana Bunches, and 1 Papaya to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Did you have luck winning any of that fruit from those darn tall and stingy trees?", completion = "Well, that's a better assortment than I would've expected from this place. Now, for the important question: can we distill it into anything drinkable? We'd better get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[12635] = { id = 12635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Snow Leopard Goddess", description = "I overheard that you are going to see to the well-being of Har'koa. Good luck to you.\n\nI am wondering if while you are in the vicinity of the altar, you would be willing to recover their relics? I do not require many, and it is only a short trip to the southeast.\n\nWhat do you say?", sourceObjective = "Chronicler To'kini at Zim'Torga wants you to recover 10 Har'koan Relics.", progress = "The Drakkari are so busy destroying themselves, it would be a shame if the historical significance of their empire were to be likewise lost.", completion = "Aw, prime specimens!\n\nYou can see there the divergence from the root symbology. Quite extraordinary.\n\nWhat a pity that the ice trolls are determined to bring about their own demise.\n\nDid you know, for instance, that the Drakkari were exiled from the rest of the troll nations for their extremely violent ways?\n\nIt's true! How did you think trolls ended up in such a harsh climate as this?", sourceObjectiveStatus = "unverified-source-field" }
quests[12636] = { id = 12636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye Of Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the master is able to see great distances into the territories held by our enemies. What the eye sees, the Lich King sees, and now the time has come for you to peer through the eye! the Lich King has called for you, {name}.\n\nGo now! Suffer well, <brother/sister>...", sourceObjective = "Report to the Lich King in Ebon Hold.", completion = "The time to spill the blood of our enemies approaches. You must first learn what it is that you seek to destroy, before rushing headlong into battle. It is what separates a {class} from a mindless ghoul.\n\nI will grant you sight beyond sight, my champion. You will use the eye of Acherus to steal our enemies' secrets.", sourceObjectiveStatus = "unverified-source-field" }
quests[12637] = { id = 12637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Near Miss", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurance. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", sourceObjective = "Stefan at Ebon Watch wants you to take the Unliving Choker to Bloodrose Datura.", progress = "Yes, {race}?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no coincidence. The creation of such a device is very involved, and the required resources would not be squandered on a random target.\n\nThe simple truth of the matter is this; You're wanted by the Scourge....", sourceObjectiveStatus = "unverified-source-field" }
quests[12638] = { id = 12638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close Call", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurence. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", sourceObjective = "Stefan at Ebon Watch wants you to take the Writhing Choker to Bloodrose Datura.", progress = "Yes, {race}?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no random act. The creation of such a device is very involved. You've somehow caught the attention of the Scourge leadership.\n\nThe question is not how, why, or even who... but what will we do about it?", sourceObjectiveStatus = "unverified-source-field" }
quests[12639] = { id = 12639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Earth", description = "We captured these elementals from nearby, and I have plenty of defenders now. But, it takes a great deal of power to make them strong enough to stand up to our enemies.\n\nThe frozen earth at Drak'Mabwa to the northwest have what I need to maintain our defenses. I'll need more of their essence if I'm to keep this up.", sourceObjective = "Element-Tamer Dagoda at Zim'Torga wants you to collect 7 Essence of the Frozen Earth.", progress = "I hope that you've returned with enough. The attacks from the Pools of Jin'Alai have become more desperate after what you did to them.", completion = "Thank you, {class}. Those essences should be enough to fuel my casting for quite some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[12640] = { id = 12640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Rifts", description = "Dagoda gonna be sendin' you northwest to Drak'Mabwa to get her more stuff for her defenders if she didn't already.\n\nWhile you up there, Ahunae be wantin' you to destroy the rifts those elementals pourin' out of. The last thing we needin' is for them to attack us!\n\nJust watch out, more of those frozen earth'll show up when you try to seal the rifts.", sourceObjective = "Scalper Ahunae at Zim'Torga has asked you to seal 7 Elemental Rifts.", completion = "Ahunae hopin' that Dagoda got all of the defenders she wantin'. With those rifts sealed, it's not likely she'll be gettin' any more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12641] = { id = 12641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Comes From On High", description = "Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple.\n\nUse the eye's siphon to analyze the forge, town hall, hold, and chapel. The eye's control mechanisms are located on either side of this platform. Waste no more time, {name}.\n\nThe Scourge will have this place. The Lich King commands it!", sourceObjective = "The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame.\n\nControl the Eye of Acherus by using the Eye of Acherus Control Mechanism.", progress = "Our assault upon the Scarlet Crusade will become legend.", completion = "They prepare for battle - as expected - but there is something else. I sense an old enemy. An enemy that I destroyed long ago...\n\nIt matters not. We will send the full might of the Scourge against them before they have a chance to evacuate their homes and put in place their defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[12642] = { id = 12642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of Rhunok", description = "My feelings tell me that Rhunok doesn't have much time.\n\nI can tell that the arctic bear god's spirit has already separated from his weakened body. It is his spirit with which you must commune.\n\nHis altar lies to the northwest beyond Drak'Mabwa.", sourceObjective = "Speak with the Spirit of Rhunok at the Altar of Rhunok.", completion = "I am barely hanging on. You must work quickly or all will be lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[12643] = { id = 12643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Lining", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the land beneath the Reliquary of Agony. Slay the ghouls and abominations you'll find there and return to me with their remnants.", sourceObjective = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", progress = "Have you brought the components I asked for, {name}?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do.\n\nNow brace yourself, {class}. This is where it gets good....", sourceObjectiveStatus = "unverified-source-field" }
quests[12644] = { id = 12644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still At It", description = "Now that we've got the raw materials, I've had my assistant ready the still. He'll oversee the process, but I want you to help keep everything under control. You might be tempted to think that we just throw everything into the still and let it sit, but you're wrong.\n\nIngredients and heat need to be added at certain times, and the pressure regulated at others. You'll have no more than 10 seconds to react to a situation. Speak with \"Tipsy\" McManus when you're ready to start distilling.", sourceObjective = "Successfully complete the distillation process and bring the completed Thunderbrew's Jungle Punch to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Well, how did it turn out?", completion = "<Grimbooze gives the cask a shake.>\n\nThere's something in here, but the million gold question is, can you drink it? Don't you go anywhere; you'll be responsible for overseeing the sampling of the product, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[12645] = { id = 12645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taste Test", description = "And now for the moment of truth!\n\n<Grimbooze chuckles.>\n\nI've always wanted to say that. Normally, I'd debut a new drink at a banquet, but we can't have one in the middle of the jungle.\n\nInstead, just take samples to a few trusted friends and return with their comments. Let's see, we'll definitely want Hemet Nesingwary's opinion, and Hadrius Harlowe's, too. They're here in camp. You'll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.", sourceObjective = "Offer a sample of Thunderbrew's Jungle Punch to Hemet Nesingwary, Hadrius Harlowe, and Tamara Wobblesprocket, then return to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Don't keep me waiting, {name}. What are the results?", completion = "Two out of three drinkers agree, eh? Not bad for a first try. Not bad at all. I suppose I'll have to whip up something else for Tamara by way of apology.\n\nNow... what should we call this creation?", sourceObjectiveStatus = "unverified-source-field" }
quests[12646] = { id = 12646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Prophet, My Enemy", description = "My prophet absorbed too much of my power too quickly, and subsequently killed himself. You can see the results at the water-filled crater to the south in Drak'Mabwa.\n\nMy former priests have already resurrected him so that he can finish the job. They're channeling my power back into him, and it will not be long now before he reawakens.\n\nYou must put an end to him and return with my mojo before it is too late.", sourceObjective = "The Spirit of Rhunok at the Altar of Rhunok has asked you to acquire his Arctic Bear God Mojo.", progress = "Quickly, {race}, do you have my mojo?", completion = "You did it.\n\nBut now there is one other thing that I need you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[12647] = { id = 12647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End to the Suffering", description = "My body is too far gone now, {name}. It is only a matter of time before a new prophet is elevated and finishes what the other began.\n\nI am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable.\n\nUse the incense and do me the kindness of putting an end to my suffering.\n\nI apologize if I fight back. Even for me, the will to survive is strong.", sourceObjective = "The Spirit of Rhunok has asked you to use the Tormentor's Incense to awaken his body. You are then to slay Rhunok using the power that his spirit has imbued you with.\n\nIf for some reason you lose the Mojo of Rhunok aura, you can return to the Spirit of Rhunok to have it reapplied.", progress = "If you do not put an end to my suffering soon, {name}, all may be lost.", completion = "You've done what had to be done and honored me in the process.\n\nI give you my deepest thanks, {name}. I only hope that you and Har'koa will be able to help the others.", sourceObjectiveStatus = "unverified-source-field" }
quests[12648] = { id = 12648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing Down", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge merchant just east of here. Return to me with a bottle of bitter plasma.", sourceObjective = "Stefan at Ebon Watch wants you to use the Ensorceled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Well, {name}?\n\nDid you purchase that flask?", completion = "So? How are you enjoying scourge life?\n\nBelieve me, it's not all it's cracked up to be....", sourceObjectiveStatus = "unverified-source-field" }
quests[12649] = { id = 12649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suit Up!", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge vendor just east of here. Return to me with a bottle of bitter plasma.", sourceObjective = "Stefan at Ebon Watch wants you to use the Ensorcelled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Well, {name}?\n\nDid you purchase that flask?", completion = "So? How are you enjoying Scourge life?\n\nBelieve me, it's not all it's cracked up to be....", sourceObjectiveStatus = "unverified-source-field" }
quests[12650] = { id = 12650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plundering Their Own", description = "There is another altar nearby where there are artifacts to be saved.\n\nIt is said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra of Drak'Mabwa, have already plundered their own holy site.\n\n{class}, I would be appreciative if you could rescue those artifacts from their undeserving hands.", sourceObjective = "Chronicler To'kini at Zim'Torga wants you to recover 7 Rhunokian Artifacts.", progress = "There is no comprehending the Drakkari. They are brutal savages who have sunk to a new low.", completion = "Let me look at those.\n\n<The chronicler examines the artifacts that you have recovered.>\n\nHmph, I'd say that we're lucky you liberated these when you did, {class}.\n\nHow very interesting. This artifact here depicts the events of the Sundering. There was a time when Northrend was the far northern portion of Kalimdor.\n\nBut after the Sundering, the land broke off, eventually becoming Northrend.\n\nThis, of course, is why we see Drakkari in the southern continents as well as here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12651] = { id = 12651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lakeside Landing", description = "When the trouble with the Venture Company started, I asked Marvin Wobblesprocket and his wife, Tamara, to take their flying machines east to River's Heart. I asked them to setup a small camp there so that we could use them as a relay to fly in supplies and survey the area.\n\nThey should have arrived by now and started setting up. River's Heart is near the center of the basin where the rivers converge. Search for Lakeshore Landing on the northeast shore. Marvin mentioned it would be the best spot.", sourceObjective = "Speak with Tamara Wobblesprocket at Lakeside Landing.", completion = "So, Hemet sent you? We were just about to let him know that we've gotten things up and running here. Please forgive Marvin if he seems to be ignoring you, but he gets very absorbed in his work.", sourceObjectiveStatus = "unverified-source-field" }
quests[12652] = { id = 12652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feedin' Da Goolz", description = "Git o'er heer, gool! Yeh, I talkin' to yoo.\n\nIt feedin' time now. Gotta git da grub ta all da gools!\n\nSpeshal grub dis time! Bowels an' brainz bowl... num, num, num.\n\nJus drop da bowl nexta da gool. Gud way ta make frenz.\n\nYoo got goolfrenz? Ha, ha, hah!", sourceObjective = "Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls.", progress = "Yoo dun feed da goolz?", completion = "Num num!", sourceObjectiveStatus = "unverified-source-field" }
quests[12653] = { id = 12653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Har'koa", description = "And now it is time for you to return to the leopard goddess. Somehow I sense that she has other plans for you.\n\nTell her that no matter what, we are eternal.", sourceObjective = "Speak with Har'koa at the Altar of Har'koa.", completion = "<The cat goddess howls in pain.>\n\nMy spirit cries out in grief at the loss of another friend. But fear not, he will return and his spirit will live on forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[12654] = { id = 12654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Part-time Hunter", description = "When Hemet asked me to accompany Marvin out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp.\n\nI wanted to take down a ferocious lion named Pitch. He's said to make his home south of here, near where the Wildgrowth Mangal meets the northern face of the Skyreach Pillar. If you can find the beast, would you bring back his remains? If the rumors are true, they'd make a trophy even Hemet will respect!", sourceObjective = "Bring Pitch's Remains to Tamara Wobblesprocket at Lakeside Landing.", progress = "Did you find Pitch?", completion = "You got it! Now all I have to do is make a trophy out of it. That'll be the hard part -- finding a way to preserve it so that Hemet doesn't have a good laugh at my expense.", sourceObjectiveStatus = "unverified-source-field" }
quests[12655] = { id = 12655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Rhuk", description = "There is another god of Zul'Drak that is being neglected.\n\nZim'Rhuk's statue lies directly to the north. Known as \"The Wise One\", Zim'Rhuk is also known to be very protective of his domain. He maintains guardians that deal harshly with anyone that does not have the wits to slip past them.\n\nAvoid the guardians and give the Drakkari offerings to Zim'Rhuk so that you will benefit from his blessing.", sourceObjective = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Rhuk.", progress = "<You sense that Zim'Rhuk does not trust you. He is attempting to call out to one of his guardians.>", completion = "<Zim'Rhuk acknowledges the offerings you intend to place before him, though he knows that you took them from the corpses of others.>\n\n<If you give the offerings to him, he reluctantly agrees to grant you his blessing.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12656] = { id = 12656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Rhuk", progress = "<Zim'Rhuk is impressed and frustrated that once more you seem to have dodged his guardians. At least for now.>\n\n<Place the offerings before him and he will grant you his blessing again.>", completion = "<Zim'Rhuk forces an image into your mind of one of his guardians squishing you beneath its foot. Perhaps you should attempt to appease Zim'Rhuk with more offerings.>" }
quests[12657] = { id = 12657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might Of The Scourge", description = "Listen well, death knight, for I give to you the words that will start a war. My final judgment has been passed: Death. To. All. None shall stand so boldly against the might of the Scourge without reprisal!\n\nAs you have served me well in your first task, so too shall you serve me in your next task. Take my judgment to Highlord Mograine at the command post of Acherus, found on the first floor. Tell him to begin the assault.\n\nAnd when the Crusade has been dealt with, we will finish off the Argent Dawn.", sourceObjective = "The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold.\n\nUse the glowing transporter behind The Lich King to reach Highlord Darion Mograine in the Hall of Command.", completion = "The horns of war will soon echo across this land, waking the dead and calling forth the Scourge war machine. Woe unto those that would stand in our way!\n\nYou and your brethren will lead the charge, {name}. When next I look upon the Scarlet lands, my sight will be obscured by the legions of Acherus. The march upon New Avalon begins now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12658] = { id = 12658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Pet Roc", description = "Dorian's had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own!\n\nNo, not a juvenile drake. I don't want a pet capable of biting my hand off!\n\nHowever, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there's a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.", sourceObjective = "Bring 7 Roc Eggs to Zootfizzle at Dorian's Outpost.", progress = "Do you have those eggs?", completion = "Oh, these are very nice! I've gotten so tired of robotic squirrels and chickens for company. It'll be wonderful to have a pet whose joints won't require oiling!", sourceObjectiveStatus = "unverified-source-field" }
quests[12659] = { id = 12659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalps!", description = "I thinkin' it be time to do some scalpin', mon!\n\nThe trolls at Heb'Drakkar to the northeast should do nicely. With their fancy bats and attackin' us, they got it comin'!\n\nAhunae even give you his own knife so that you do the job right.", sourceObjective = "Scalper Ahunae at Zim'Torga wants you to use Ahunae's Knife to scalp 10 Heb'Drakkar trolls.\n\nThe scalper reminds you that you should loot them first.", completion = "Aw, me thinkin' that too funny.\n\n{name} is my kind of {race}!\n\nYou still got my knife?", sourceObjectiveStatus = "unverified-source-field" }
quests[12660] = { id = 12660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Destruction", description = "The Lich King's lackeys have dared to bring weapons of destruction into my domain.  I will not stand for this.\n\nGo to their outpost to the north and destroy the weapons they would use against the land.  We cannot let the Scourge taint another inch of these sacred lands.", sourceObjective = "The Avatar of Freya wants you to go to the Death's Hand Encampment to the northwest and destroy 4 Unstable Explosives.", progress = "Is it done, {name}?", completion = "I thank you, {race}.  You're proving to be a worthy ally.", sourceObjectiveStatus = "unverified-source-field" }
quests[12661] = { id = 12661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Voltarus", description = "By now you've probably guessed the details of my plan.\n\nWe're using the Scourge's interest in you against them. You're going undercover. I know it's likely a death sentence, but if we do nothing your death is a certainty.\n\nTravel northeast to Reliquary of Pain and stand on the platform while wearing your disguise. Once inside Voltarus, you must earn the trust of the Scourge commander.\n\nWhen you've completed your mission, blow this horn and I'll fly to your location to receive your report.", sourceObjective = "Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", completion = "Well, now... I must admit I'm more than a little surprised to see you, {name}.\n\nTell me what you've learned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12662] = { id = 12662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing Down Heb'Jin", description = "<Dagoda looks at Ahunae and sighs.>\n\nYou want to really deal with Heb'Drakkar? Collecting scalps isn't going to get the job done. You have to take out their leader, Heb'Jin.\n\nThe problem is, he's up on the bat rookery goading his forces on.\n\nBang his drum and I guarantee that he'll fly down. That's when you kill him.\n\nYou can take this net we got from one of his headhunters. Use it to trap his bat when he lands. That way you won't have to fight both of them.", sourceObjective = "Element-Tamer Dagoda at Zim'Torga wants you to kill Heb'Jin.", completion = "You did it!\n\n<Dagoda gives you a big kiss on the cheek.>\n\nYou have no idea how much of a relief that is to me! Defending against trolls on all sides is really putting a strain on us. Not to mention his incessant yelling.\n\nPlease, {name}, take your pick of what we have to offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12663] = { id = 12663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reunited", description = "{name}!\n\nYa musta received mah gift! Turn around, mon, lemme get a good look at ya... Ahh, ya make me proud.\n\nWe come such a long way, you and I, and now we be servin' da Lich King together.\n\nStick with me and big things be comin, mon. Big things... but first, we need to be gettin' ya caught up. So much been happenin' since I saw ya last.\n\nGo speak ta Gorebag for a tour of Zul'Drak. Listen for me and I'll tell ya all ya be needin' ta know.", sourceObjective = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", progress = "You an' me gunna take Gundrak, mon.", completion = "So, now ya be seein' what we be up against, mon.\n\nGo down, take some time ta learn da land, prepare some strategy. \n\nI'll be havin' some tasks for ya soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12664] = { id = 12664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Horizon", description = "Ahh, another supplicant answerin' da Lich King's call.\n\n<Drakuru sniffs you.>\n\nFreshly scourged, eh? Ya still be reekin' of da living!\n\nLong be da line of dem who seek da Lich King's blessings. Ya must rise above da masses and prove yerself worthy of wieldin' true power.\n\nLookin' down over Zul'Drak, I sensed potential in ya. I ordered your - invitation.\n\nDa rest be up ta you....\n\nGo an' speak ta Gorebag for a tour of Zul'Drak. Dere be much ta do if you're to be of any worth to me.", sourceObjective = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", progress = "Have ya taken in da battlefield yet, mon?", completion = "So, now ya be seein' what we be up against, mon.\n\nI want ya ta go down, learn da land, mingle with yer bretheren. Prepare yourself...\n\nSoon, dere be much for ya to do. Don't ya be disappointin' me!", sourceObjectiveStatus = "unverified-source-field" }
quests[12665] = { id = 12665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Sense a Disturbance", description = "There's something wrong with Quetz'lun, the wind serpent goddess. What it is exactly I cannot sense, but I do know that her altar has been overrun with powerful creatures.\n\nI'm going to send you there on the back of one of my children, which you saved. The two of you will move swiftly and with great stealth to uncover what has become of Quetz'lun.\n\nMy child will see you safely back to me. Just keep your eyes open.\n\nWhen you are ready, ask and I will call one of my kittens for you.", sourceObjective = "Har'koa has asked you to determine what has happened to Quetz'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz'lun.\n\nReturn to her at the Altar of Har'koa once you have done so.", progress = "What seems to be the delay, {name}?", completion = "Thank you for bringing my kitten back safely.\n\nDeep down I knew it. I wanted to deny it, but your eyes have revealed the truth.\n\nNevertheless, I sense something else. All is not as it seems.", sourceObjectiveStatus = "unverified-source-field" }
quests[12666] = { id = 12666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for the Underworld", description = "Quetz'lun may be dead, but I can still feel her spirit lingering in the underworld at the altar. We have to find a way to get you to her.\n\nLuckily for us, I just happen to have a supply of former supplicants at hand who are no longer in need of their sacred adornments. Both my subduers and claws are likely to still be wearing them.\n\nBring the adornments to me and I'll draw upon their energy to enable you to cross over into Quetz'lun's underworld nightmare.", sourceObjective = "Har'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har'koa.", progress = "I never imagined that it would come to this. The Drakkari are truly lost.", completion = "<The leopard goddess looks saddened at the collection of holy symbols that you have brought before her.>\n\nThere was a time when these meant something. Let's see if we can put them to better use.", sourceObjectiveStatus = "unverified-source-field" }
quests[12667] = { id = 12667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Wind Serpent Goddess", description = "You are prepared, but I'm not certain that you're ready for what is to come.\n\nWhen you cross back over into Quetz'lun's altar area, you will enter the realm of the dead. From what I can feel of it, it's not going to be pleasant.\n\nTry not to be distracted by what you see in there. Simply head for the altar building and seek out Quetz'lun's Spirit.", sourceObjective = "Seek Quetz'lun's Spirit at the Altar of Quetz'lun.", completion = "{race} worm. Tell me why I should not annihilate you where you stand?", sourceObjectiveStatus = "unverified-source-field" }
quests[12668] = { id = 12668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foundation for Revenge", description = "I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge.\n\nYou do still want to live, yes?\n\nAs you have seen, my devotees are enjoying their stay here, but now it's time for them to make final restitution.\n\nDo me the smallest of favors if you would, {name}. Lure them near my soul fonts and then put an end to their existences.\n\nThey taste so delicious, and their sacrifice will not go in vain, I can assure you.", sourceObjective = "Quetz'lun's Spirit has tasked you with the destruction of 12 trolls, either Quetz'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts.\n\nOnly after you have accomplished this should you return to her at the Altar of Quetz'lun.", progress = "Why do you return when your task is not yet complete? Do you not realize that I can destroy you with but a thought?\n\nGo now, little {race}. Complete that which I commanded of you!", completion = "Exquisite. Perhaps you will be of some use after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[12669] = { id = 12669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So Far, So Bad", description = "Everything you've reported is consistent with what we know. Learning of Drakuru and earning his trust will lay the groundwork for your future missions.\n\nReturn to him and do as he says. Do whatever you must to appear sincere, {name}. A great deal is riding upon your performance.\n\nThis time I'm adding an additional assignment: While you're in the field, pour this additive into their blight cauldrons. It should neutralize the scourging agent and render the batch useless.", sourceObjective = "Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you.\n\nWhile at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Please, {name}, tell me you haven't blown your cover....", completion = "Nice work, {name}!\n\nDiluting those cauldrons will not only save lives, it will slow the growth of the Scourge in this region.\n\nNow come, tell me what you've learned of Drakuru's strategy in Zul'Drak.", sourceObjectiveStatus = "unverified-source-field" }
quests[12670] = { id = 12670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Harvest", description = "Below Acherus stands Death's Breach, the staging point for our assault upon the Scarlet Crusade. You are to ride one of my Scourge gryphons, located on either side of this platform, and report to Prince Valanar. Do as he says and you may live to see these lands fall before us.", sourceObjective = "Report to Prince Valanar at Death's Breach.", completion = "Do you smell it?\n\n<Valanar sniffs at the air.>\n\nFresh meat... The scent of Scarlet Crusader wafts through the air.\n\n<Valanar salivates.>\n\nApologies, {class}, I'm sure you're not interested in my choice of fine cuisine. You are here to work! To lead the charge! Yes... I know. The Lich King has told me all that I need to know about you, {name}.\n\nThe time for bloodshed is now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12671] = { id = 12671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconnaissance Flight", description = "It's about time we had planes up and running in this place.  The professor's been asking me to check out a strange weather pattern coming from the northeast.\n\nThing is, I'm going to need a co-pilot if we're going into uncharted territory.  No way in hell I'm heading out there alone.\n\nWhat do you say, <tough-guy/hotshot>?  You might learn a thing or two.  And once you learn to deal with the northern winds... you can pretty much fly anywhere.", sourceObjective = "Help Pilot Vic complete the Reconnaissance Flight.", completion = "You saved my life up there, buddy.  Nice flying!", sourceObjectiveStatus = "unverified-source-field" }
quests[12672] = { id = 12672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Stage", description = "I will give you a chance at continued existence.\n\nThere are fragments of the power that fueled my curse scattered about the altar grounds. It is my desire that you collect some of them for me. Not so many that the curse will be lifted, but enough that I will be able to eventually make use of them to exact revenge upon my prophet.\n\nGo, insect. Run and do my bidding before I change my mind about letting you live.", sourceObjective = "Quetz'lun's Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz'lun only when you have done so.", progress = "What a shame that Har'koa didn't send you along sooner. Then again, she and I never did get along.\n\nShe probably held back your help just long enough for this to happen.", completion = "They'll do. Likely I won't even need them.\n\nBut it was fun watching you run around at my command.", sourceObjectiveStatus = "unverified-source-field" }
quests[12673] = { id = 12673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Rolls Downhill", description = "If ya ever gonna be worthy of da Lich King's gifts, ya must learn ta be a great leader - one who be commandin' respect!\n\nI got a task dat gonna refine your command skills, mon....\n\nSumma my minions be trained ta harvest blight crystals from da land below, but dey be lazy and slow. You gonna be in charge o' dem, mon.\n\nTake dis scepter and teach 'em how to get da job done. When dey be under your control, make 'em harvest dem crystals!", sourceObjective = "Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals.", progress = "Ya got my underlings whipped into shape, {name}?", completion = "Da crystals be pilin' up like never before!\n\nYou keep up da good work, {name}. I got more tasks for ya real soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12674] = { id = 12674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hell Hath a Fury", description = "It is now time for you to punish my three high priests: Mu'funu, Tua-Tua, and Hawinni. You'll find them spread around the altar grounds.\n\nTake this hexxing stick. I've empowered it with my rage and indignation. I'm sure that it will prove potent.\n\nJust use it and proceed to destroy them. The hex will take care of the rest.\n\n<Quetz'lun displays a toothy grin.>\n\nSucceed and I may let you go. Fail and die.", sourceObjective = "Quetz'lun's Spirit at the Altar of Quetz'lun wants you to use Quetz'lun's Hexxing Stick upon High Priest Mu'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them.", progress = "DO YOU THINK THAT I'M A FOOL?\n\nTHEY'RE NOT DEAD!", completion = "<The terrible spirit before you lets loose a blood-chilling cackle.>\n\nThey had it coming. And I'll give them more of the same again and again and again....", sourceObjectiveStatus = "unverified-source-field" }
quests[12675] = { id = 12675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Thing", description = "There is one last thing that is needed to enact the final revenge against my prophet. The power fragments you collected must be imbued with a portion of a living gods' spirit. You're going to need to beseech Har'koa for some of hers.\n\nOnce you've done that, when you return here, you will not come to the underworld. Instead, you will return to the physical world of my altar. My children and guardians will no longer attack you, and you'll be able to get to my prophet without having to worry about them.", sourceObjective = "Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa.", progress = "You've returned, {name}.", completion = "A portion of my spirit?\n\n<The snow leopard goddess pauses a moment to consider.>\n\nThat's quite an expensive gift considering that this is for revenge and I'm already greatly weakened by the actions of my subduers.\n\nStill, I may know a way.", sourceObjectiveStatus = "unverified-source-field" }
quests[12676] = { id = 12676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage", description = "While we're working to discover the purpose of these crystals, we need you back in Voltarus doing Drakuru's bidding.\n\nEvery task you perform successfully gets you closer to him, and brings us that much nearer to knowing his mind.\n\nWhile you're there, I have another mission for you. Drakuru's Scourgewagons pose a significant threat. We need them destroyed. \n\nMake your way to the wagons and activate these charges. Once they're set, get clear! The explosion will expose you if you're too close.", sourceObjective = "Stefan at Ebon Watch wants you to perform another task for Drakuru.\n\nAdditionally, you are to use the Explosive Charges on 5 Scourgewagons at the  Reliquary of Pain.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Were you successful in clearing those scourgewagons, {name}?", completion = "Excellent!\n\nYour undercover work has truly paid off, {name}.\n\nNow let's have a look at that scepter....", sourceObjectiveStatus = "unverified-source-field" }
quests[12677] = { id = 12677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazardous Materials", description = "Blight crystals?! What could this scumbag Drakuru be up to? Clearly, he's working on something significant.\n\nContinue to do his bidding and perhaps once he's more familiar with you he'll reveal his plans. In the meantime, we need to have a look at these crystals.\n\nWhile you're in Voltarus, try to get some samples of the harvested crystals when no one's looking.\n\nBe alert! Handling those crystals can trigger your disguise to fail.", sourceObjective = "Stefan at Ebon Watch wants you to go to Voltarus and complete any tasks Drakuru has for you. While there, you are to steal 5 Harvested Blight Crystals.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Welcome back, {name}.\n\nWere you able to steal any samples of Drakuru's crystals?", completion = "Fascinating!\n\nWe'll look into the properties of these crystals right away.\n\nNow tell me, {name}, what is the latest with this Drakuru fellow?", sourceObjectiveStatus = "unverified-source-field" }
quests[12678] = { id = 12678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Chaos Drives, Let Suffering Hold The Reins", description = "They make their stand now, outside of Death's Breach, futilely attempting to push us back in hopes of saving their horses, mines, lumber and citizens.\n\nThis will be your first lesson in Scourge warfare: TERROR!\n\nGo to the front lines, south of here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for the death march.\n\nBut most importantly: kill the fleeing villagers. Soldiers dying are an affordance, but villagers? That is what strikes fear into the hearts of man.", sourceObjective = "Prince Valanar at Death's Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire.", completion = "Do you feel it, {name}? That sensation is raw power coursing through your body. Such a thing cannot exist for mortals.\n\nThe front lines are now dismantled. The geist will finish the job and prepare the grounds for Razuvious. We turn our attention now to more tactical targets.", sourceObjectiveStatus = "unverified-source-field" }
quests[12679] = { id = 12679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonight We Dine In Havenshire", description = "The Sky Darkeners are mindless constructs with one purpose: KILL! Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire for the safety of New Avalon. We certainly can't allow those cowards to make it to safety and then take up arms against us!\n\nThere is one slight problem. They use saronite arrows for maximum range and damage. Saronite, however, is a metal only found in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward you handsomely.", sourceObjective = "Orithos the Sky Darkener at Death's Breach wants you to recover 15 Saronite Arrows.", progress = "The trajectories they are firing at would have most of the arrows land at or near the Havenshire Farm, south of us.", completion = "Well done, {class}! You feed the Scourge war machine with your deeds!\n\nAh yes, your reward - as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[12680] = { id = 12680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Palomino", description = "How fortuitous it is that the Crusade has a stable full of horses a mere stone's throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully <his/hers>!\n\nOnce you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger.\n\nRemember, {name}, it's only stealing if you're caught. Watch out for that deranged stable master, Kitrik!", sourceObjective = "Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death's Breach.", progress = "You don't want to walk forever, do you?", completion = "Now for the true test. Can you show mastery over an unbound charger and brutally overtake the thing that you desire most?", sourceObjectiveStatus = "unverified-source-field" }
quests[12681] = { id = 12681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagent Agent", description = "That Archmage Pentarus, back in Dalaran, will be expecting us to return with all kinds of reagents and talismans. It seems the locals are fond of animal parts. Twisted claws from the goretalon rocs are among their favorite.\n\nIt's not my place to say whether the rumors are true or not, but I've a feeling there's something here.\n\nThe rocs live in the Bonefields off to the northeast, where they feed on the corpses of old mammoths. Will you help me gather talons for the archmage's research?", sourceObjective = "Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian's Outpost.", progress = "Were you able to find any of the twisted talons?", completion = "<Colvin looks admiringly at the talons you've brought back.>\n\nThese will more than suffice. The gorlocs have a saying that the more gnarled the talon, the more power it holds. I'm sure the archmage will get his money's worth from this expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[12683] = { id = 12683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning to Help", description = "There's no more caustic material in all of the basin than bittertide hydra sputum. I've got special containers to collect just such a thing for Archmage Pentarus' studies. Now all I need is a brave, um... collector.\n\nYou look like a hardy, adventurous {class}. How'd you like to make a bit of money and aid Dalaran's cause at the same time?\n\nAll you need to do is take this container with you to Bittertide Lake, to the southwest. Engage the hydra and use the container to sample the sputum they shower you with.", sourceObjective = "Colvin Norrington at Dorian's Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra.", progress = "Did you get those samples?", completion = "Wonderful! Here's your payment, as agreed. And, uh, a bit of advice: you might want to enjoy long, hot baths the next few days if that 'burning sensation' persists.", sourceObjectiveStatus = "unverified-source-field" }
quests[12684] = { id = 12684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of a Dead God", description = "Mam'toth, the god of the mammoths, destroyed himself, and took much of his temple with him, rather than allowing his trolls to gain his power.\n\nIf I'm to sacrifice a portion of my spirit, I will need something with which to bolster myself.\n\nMam'toth left behind an enormous crater to the northeast, just north of the Altar of Quetz'lun. Within the crater his blood yet lives.\n\nBring it to me.", sourceObjective = "Har'koa has asked you to collect 7 Blood of Mam'toth. Return them to her at the Altar of Har'koa.", progress = "I wish that there were something that we could do to bring Mam'toth back to life, but there isn't.\n\nWe can honor him and his sacrifice by continuing the fight against the Drakkari.", completion = "Very well. Let us see if this works....", sourceObjectiveStatus = "unverified-source-field" }
quests[12685] = { id = 12685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Reap What You Sow", description = "This is what it has come down to... revenge.\n\n<Har'koa sighs.>\n\nTake this ritual kit and enact it near Quetz'lun's corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet.\n\nThe rest will be up to you, {name}. You must slay the prophet in his drained state.", sourceObjective = "Slay the Drained Prophet of Quetz'lun and then inform Witch Doctor Khufu at Zim'Torga.", completion = "<The witch doctor shakes his head in disbelief.>\n\nIt sounds like you barely escaped Quetz'lun's underworld alive.\n\nI'm glad that it's you out there. I don't know if I would have had the courage to deal with that situation!", sourceObjectiveStatus = "unverified-source-field" }
quests[12686] = { id = 12686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zero Tolerance", description = "Ignorance! Dis be intolerable, mon! My entire batch of blight be useless!\n\nDat mongrel, Darmuk! He be responsible for watchin over da blight. He failed me, mon!\n\nDis be a good lesson for ya, {name}. Failure be like a disease dat spreads. Ya gotta catch it and kill it early, before it be killin' you!\n\nTake dis scepter. It make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin' down below just to da south.\n\nLet dat be an example to all, mon. Don't be failin' Drakuru!", sourceObjective = "Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk.", progress = "Has Darmuk paid for his failure, {name}?", completion = "Ya done good, {name}. You be learnin' faster than I had hoped.\n\nGo now, get ya some rest. Soon I be givin' ya an even greater test!", sourceObjectiveStatus = "unverified-source-field" }
quests[12687] = { id = 12687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Realm of Shadows", description = "The horse you stole has been taken to the Realm of Shadows. It is there that my dark rider will slay the beast and raise it as a deathcharger. Do you think yourself brave enough to enter the Realm of Shadows in pursuit of the deathcharger?\n\nIf you accept, I will transport you to the shadow world. Once there, seek out a dark rider in the open fields south of us. To emerge victorious you must slay him, overtake his deathcharger and return it to Death's Breach. Issue the Horseman's Call should you succeed.", sourceObjective = "Salanar the Horseman at Death's Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger.\n\nShould you succeed, return the Acherus Deathcharger to Death's Breach and use the Horseman's Call to summon Salanar.", progress = "You must take the deathcharger by force, {class}!", completion = "You have succeeded where most initiates fail, {name}. For that you will be rewarded handsomely.", sourceObjectiveStatus = "unverified-source-field" }
quests[12688] = { id = 12688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering a Disaster", description = "These goblin goons and their minions have decided that they own this pillar and its crystals. I came here to explore the crystals and take samples, but they overpowered me and won't let me return to the camp.\n\nIf you'll help me fight our way out of here, we can teach these thugs a lesson they'll never forget!", sourceObjective = "Help Engineer Helice escape from Swindlegrin's Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp.", completion = "Thank you for freeing Helice and seeing to her safe return. We all started to get worried when she didn't return from her crystal hunting trip.", sourceObjectiveStatus = "unverified-source-field" }
quests[12689] = { id = 12689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand of the Oracles", sourceObjective = "Hi! Really glad see you again!\n\nI knew we friends. I knew it! You good friend. Not just for us, but for all Oracles. Thank you for saving us! Thank you, thank you!\n\nI saw you bonk that puppy-man good! Undead thing said he your friend before? I not know that. You done with puppy-men though, yeah? Just Oracle friend now?\n\nStop! No agree without thinking - you sure you not want to be friends with puppy-men anymore?", sourceObjectiveStatus = "unverified-source-field" }
quests[12690] = { id = 12690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel for the Fire", description = "It be time we start our march to Gundrak, mon. It be time for me ta turn ya loose on dem trolls!\n\nDey breached our wall and put a whole army just north of us.\n\nHahaha!\n\nDey be fuel for da fire, mon! We gunna take da chieftiains an' kill da rest! It all be part of my master plan....\n\nYou take dis scepter and go command my abominations. Bring 'em to da Drakkari army and kill em all! When da chieftains come, my pet Shalewing gunna snatch 'em up and bring 'em here to me.", sourceObjective = "Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains.\n\nChieftains will appear when enough Skullcrushers have been slain.", progress = "Did ya smash da trolls, {name}?", completion = "We done it, mon!\n\nI got da chieftains all caged up and you led my abominations to victory over their armies.\n\nIt be time ta celebrate, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12691] = { id = 12691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timeworn Coffer", description = "The stone coffer appears to be locked.  It appears that a key fits inside a large stone keyhole.\n\nPerhaps one of the guardians in the vicinity has this key in its possession.", sourceObjective = "Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker's Overlook.", progress = "The stone coffer does not budge.", completion = "The huge stone key turns with a deep grunt as the coffer lid opens up to reveal hidden treasure inside.", sourceObjectiveStatus = "unverified-source-field" }
quests[12692] = { id = 12692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Lich Hunter", description = "Okay, I going back to Frenzyheart Hill to make sure all Frenzyheart know what you done for wolvar and for Zepik. You great hunter and they dumb to think you not.\n\nGo back to hill and talk to Elder Harkek... I make sure he knows you not traitor before any other Frenzyheart.\n\nThank you, Lich Hunter.", sourceObjective = "Return to Frenzyheart Hill and speak to Elder Harkek.", completion = "It good to see you again. I knew you not a traitor, I glad Zepik prove me right.\n\nI hear you Lich Hunter now - that pretty good! You make Harkek proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[12695] = { id = 12695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Friendly Dryskin", description = "Yay! Soo-say probably worrying about us! Maybe you go back to town and tell him everything okay? Yeah, go tell Soo-say.\n\nI going grab shiny ball thing from dead lich guy - I meet you there! Go go! I meet you there!", sourceObjective = "Return to Rainspeaker Canopy and speak to High-Oracle Soo-say.", completion = "Good to see you again! We worried when you not come back right away.\n\nJaloot beat you back - lot of energy in Jaloot, he pretty fast. He told me how you save him from lich thing. Moodle told me how you save mosswalkers too. You really nice.\n\nI hope you stay with us for while. Always something need doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[12696] = { id = 12696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Surveillance", description = "You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northeast.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.", sourceObjective = "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.", completion = "The professor sent you my way?  All right.", sourceObjectiveStatus = "unverified-source-field" }
quests[12697] = { id = 12697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gothik the Harvester", description = "CHAOS, {name}! The Crusade is in a frenzy. They have diverted all forces outside of New Avalon to set up a blockade at Light's Point, east of here. They are desperately trying to strip the Havenshire Mine of all resources and load the cargo aboard the frigates they have docked on the coast.\n\nLet's stir things up a bit, shall we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his presence. He has a gift he'd like to bestow upon the Scarlet Crusade. Seek him out.", sourceObjective = "Speak with Gothik the Harvester at Death's Breach.", completion = "You have fought hard to invade the realm of the harvester... Wait.\n\n<Gothik looks at his notes.>\n\nMy apologies, {race}. Old habits die hard.\n\nValanar sent you, then? I trust you are somewhat competent.\n\nI do have a gift for the Scarlet dogs. One that is sure to speed up their work in the mines.", sourceObjectiveStatus = "unverified-source-field" }
quests[12698] = { id = 12698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift That Keeps On Giving", description = "I have come from the frozen heart of Naxxramas to feast on souls and deliver a vicious thrashing upon our sworn enemies - and I'm all out of souls.\n\nThis device I am about to give to you is a portable plague spreader. Take it east, to the Havenshire Mines, and unleash it near the Scarlet miners working inside. Use it to turn the miners into ghouls and return to me when you have a small army at your side. I have saved a special place for them in the vacuum cleaner of souls!", sourceObjective = "Gothik the Harvester at Death's Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik.", progress = "One small note: miners don't always become ghouls. Sometimes they turn into enraged spirits, hell-bent on killing you.", completion = "They now know that the mines are no longer safe. They will double their efforts in retreating, leaving their backs open to us!", sourceObjectiveStatus = "unverified-source-field" }
quests[12699] = { id = 12699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Embarassing Incident", description = "There's one little problem we have to solve before we head out.  You see, I can't seem to find the keys to my flying machine.\n\nI've looked pretty much everywhere for them... maybe you can give me a hand.  Only place I haven't looked yet is inside the lake.\n\nI'll even give you my very own air tank.  It's almost empty, but it's got a couple of hits left.", sourceObjective = "Look for Vic's Keys inside the lake at River's Heart.", progress = "You find anything yet, {name}?", completion = "Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[12700] = { id = 12700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Attack Of Opportunity", description = "Only the Scarlet forces at New Avalon and Light's Point challenge us! The time to attack the Scarlet fleet at Light's Point has come.\n\nThe diversion at the mine has caused chaos amidst their ranks. They are frantically working to clear the area and return to their ships.\n\nThe time is ripe! Prince Valanar is seizing this opportunity to finish off the Scarlet fleet. Report to him at once!", sourceObjective = "Speak with Prince Valanar at Death's Breach.", completion = "You have served us well, {class}. Few of your brethren have survived our initial attack upon the Scarlet interlopers. You remain as one of the strongest.\n\n\n\nEast of us, past the Havenshire Mine, is the coast - called Light's Point by the Scarlet Crusade. A thousand soldiers stand between us and their ships. Insurmountable? Hardly the point...", sourceObjectiveStatus = "unverified-source-field" }
quests[12701] = { id = 12701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massacre At Light's Point", description = "In their haste the Crusade will make one fatal error: forgetting to check the mine cars.\n\nYou are to return to Havenshire Mine, east of here, and locate the mine car that my minions have planted near the outhouse. Climb inside the mine car and a Scarlet miner will unwittingly see to it that you are placed safely behind enemy lines.\n\nOnce aboard one of their ships, use the cannons against them! SLAUGHTER THEM ALL!\n\nCall the Scourge gryphon from the cannon when you are ready to return.", sourceObjective = "Prince Valanar at Death's Breach has commanded you to slaughter 100 Scarlet Defenders.", progress = "Death knights know no fear!", completion = "The entire Scarlet fleet wiped out in a matter of minutes! I will receive a commendation from the Lich King for this! All that remains of the Scarlet Crusade now are the denizens of New Avalon.\n\nI'll set the fire starters and necromancers upon Havenshire immediately. You will carry my report to the Highlord!", sourceObjectiveStatus = "unverified-source-field" }
quests[12702] = { id = 12702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken Party!", description = "I bet you not guess what happen again.\n\nNope, not Goregek or chickens.\n\nOkay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly belly.\n\nLet me know if you need help from any of the hunters... they around here somewhere.", sourceObjective = "Capture 12 Chicken Escapees for Elder Harkek at Frenzyheart Hill.", progress = "Chickens not get far usually... if wasps not eat them, maybe we just let them stay on field next time.", completion = "You good at this.\n\nMaybe someday we just dump Goregek in river so you not have to do this no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12703] = { id = 12703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kartak's Rampage", description = "You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for battle. Maybe you strong enough to call Kartak even.\n\nBig battle at Kartak's Hold to southwest.  Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood to altar in Kartak's Hold to call Kartak for delicious feast of big-tongue.\n\nKartak take your body if you worthy... with Kartak's powers, you slaughter more big-tongues than even best dreams.\n\nGo kill lots, hunter!", sourceObjective = "Bring a pure sample of Oracle Blood to the Altar of Kartak to summon Kartak. With the aid of Kartak's shared powers, slaughter 50 of the nearby Sparktouched Gorlocs for Shaman Jakjek in Kartak's Hold.", progress = "So many big-tongues to kill! So fun, eh?", completion = "Ritual went so easy for you!\n\nYou come back later for more killing someday, okay?", sourceObjectiveStatus = "unverified-source-field" }
quests[12704] = { id = 12704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appeasing the Great Rain Stone", description = "Since mosswalker been attacked I worried maybe we not good to Great Rain Stone... we maybe too greedy. We need more treasures to offer!\n\nYou good at finding shinies last time... maybe you go look more around village for shinies? You maybe need one of good Rainspeakers for help. Just tell us who.", sourceObjective = "High-Oracle Soo-say in Rainspeaker Canopy wants you to take a companion to dig up and collect 6 Shiny Treasures.\n\nBe sure to speak to High-Oracle Soo-say in Rainspeaker Canopy about securing the aid of one of your previous companions.", progress = "Never enough shinies... Great Rain Stone good to us, we need be good to Great Rain Stone.", completion = "So many good shinies! You good at this.\n\nCome back for more again later, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[12705] = { id = 12705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Titans", description = "Puppy-men been attacking Sparktouched... we need fight or they just attack other Oracles too.\n\nYou been good friend to us, so maybe we allow you special honor. Great Ones left protector long time ago for shrines... it here still, but it not know something wrong til shrines messed with.\n\nPuppy-men down there have bad crystals for making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to help.\n\nDon't be scared if Soo-holu take your body... he very powerful, so he keep you safe.", sourceObjective = "Obtain a Tainted Crystal from the wolvar near Sparktouched Haven and bring it to the Great Lightning Stone to call Soo-holu. With the aid of Soo-holu's shared powers, kill 50 of the nearby Frenzyheart wolvar, then return to Lightningcaller Soo-met near the Great Lightning Stone.", progress = "Thank you for help dryskin. You very good to us.", completion = "Soo-holu strong, huh? I very glad he accept you to share his body for fight.\n\nHe more trusting of people he met before, so maybe come back another time to help more, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[12706] = { id = 12706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory At Death's Breach!", description = "<Prince Valanar hands you a sealed scroll.>\n\nThis is the full report of our victory at Death's Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, {name}.\n\nGo now!", sourceObjective = "Deliver Prince Valanar's Report to Highlord Darion Mograine in Acherus: The Ebon Hold.", progress = "I was certain you wouldn't make it back here in one piece, {class}. Perhaps there is more to you than I first surmised.", completion = "<Highlord Mograine reads over the report.>\n\nThe ENTIRE Scarlet fleet?\n\n<Highlord Mograine nods.>\n\nSuch power, {name}... I have not seen such a display of domination in years... Since my father wielded...\n\n\n\nIt's not important...\n\nYes, your commendation, lest I forget.", sourceObjectiveStatus = "unverified-source-field" }
quests[12707] = { id = 12707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wooly Justice", description = "Ahunae hear about your trip to Mam'toth Crater, mon. The children of Mam'toth are enraged and cry out for justice!\n\nFollow the avenue northeast up the steps to the next tier of Zul'Drak. On your right you will find what's left of the Altar of Mam'toth.\n\nWhen you get there, flash this Medallion of Mam'toth in front of the eyes of one of the enraged mammoths. It'll calm down for a little while, letting you hop on its back.\n\nRide it around, trampling all of the Mam'toth disciples that you can find!", sourceObjective = "Scalper Ahunae at Zim'Torga wants you to use the Medallion of Mam'toth to calm and ride an Enraged Mammoth. You are then to trample 12 Mam'toth Disciples to death.", progress = "What? You done already?\n\nDid you enact wooly justice upon those sorry ice trolls?", completion = "Score one for the victims, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12708] = { id = 12708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Tiki Warriors", description = "I know that you're headed up to the Zol'Maz Stronghold to the northeast, {class}. While you're there, I need you to deal with the warlord's special guardians.\n\nThe enchanted tiki warriors, as they're called, represent a very real threat. If the Drakkari were to mass produce them, we'd quickly be overrun.\n\nLet's you and I demonstrate that they're not worth the effort to create, shall we?", sourceObjective = "Element-Tamer Dagoda at Zim'Torga has asked you to destroy 12 Enchanted Tiki Warriors.", completion = "That should make them think twice about making more of those things. I shudder to think what it would be like to have to fight an army of those things.\n\n<The element-tamer is thoughtful for a moment.>\n\nI guess it would be just like fighting the endless waves of the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12709] = { id = 12709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexed Caches", description = "Pardon me, {name}. I'm given to understand that you might be heading northeast up to the Zol'Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering.\n\nAs I have come to know, the Drakkari warlord is extremely paranoid. He's had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say?\n\nIf you could find the time to acquire some of those goods, I would be most appreciative.", sourceObjective = "Chronicler To'kini at Zim'Torga has asked you to acquire 12 Zol'Maz Stronghold Caches.", progress = "Perhaps you carry the caches within your pack even as we speak?", completion = "Just look at all of that!\n\nSee here, {name}. This piece you recovered vividly illustrates that the Drakkari became aware of the weakening of the land that the Scourge caused by their presence.\n\nThe warlord felt compelled to take the opportunity this presented. He pushed the prophets to kill their gods in an effort to control the power and fight back against the Lich King's forces.\n\nEither way they were doomed. They inadvertently chose to be the instrument of their own destruction!", sourceObjectiveStatus = "unverified-source-field" }
quests[12710] = { id = 12710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disclosure", description = "Ya doin' well, {name}.\n\nYou be provin' dat I got an eye for talent! Now ya see why da Lich King gave me his blessing....\n\nDa time has come for me to reveal my master plan to ya, mon.\n\nNow you be seein' how we gunna sweep through da swarms of Drakkari trolls to take our rightful place in da great palace of Gundrak.\n\nTake dis scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper chamber and witness for yourself our secret weapons.", sourceObjective = "Drakuru in Voltarus wants you to take the teleporter to his upper chamber.", progress = "Have ya gone ta witness my creations, {name}?", completion = "So, there ya have it, mon.\n\nWe be makin' da ultimate scourge army ta serve da Lich King. He gunna be most pleased!\n\nYou keep da scepter, {name}. You gunna be needin' it ta command my army in battle....\n\nSoon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12711] = { id = 12711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Mail", sourceObjective = "Atop the mailbox are several illegible letters and scrolls. Useless...\n\nPerhaps you should check inside?", sourceObjectiveStatus = "unverified-source-field" }
quests[12712] = { id = 12712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key of Warlord Zol'Maz", description = "{name}, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter.\n\nThe Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast.\n\nThe warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.", sourceObjective = "Har'koa at Zim'Torga has asked you to acquire the Key of Warlord Zol'Maz.", progress = "I cannot stress how important it is that you acquire the warlord's key no matter the cost.", completion = "It might have been better if I hadn't asked you to bring it back here instead of heading directly to Gundrak.\n\nHowever, I think that it's best that you hear what else I have to say first.", sourceObjectiveStatus = "unverified-source-field" }
quests[12713] = { id = 12713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal", description = "The time has come to end this charade, {name}.\n\nAs valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed.\n\nWe've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him.\n\nFight well.", sourceObjective = "Stefan in Ebon Watch wants you to defeat Drakuru.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Have you faced Drakuru in battle, {name}?", completion = "So, it is done.\n\nWe still have much to do, but our work here will be much more manageable thanks to your efforts.\n\nPlease accept this as a token of our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[12714] = { id = 12714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will Of The Lich King", description = "It is the will of the Lich King that drives us onward, {name}. None are more aware of this than death knights. Our very existence is intrinsically tied to his consciousness. Surely you have heard him speak to you - invading your thoughts...\n\nCan you hear him now? Perhaps it is too early for you.\n\n<Mograine closes his eyes and nods to an unseen host.>\n\nYes, my lord. It will be done.\n\n{name}, you are to return to Death's Breach and report to Prince Valanar. The Lich King commands it!", sourceObjective = "Return to Death's Breach and report to Prince Valanar.", completion = "Havenshire is ours! A thousand corpses litter the ground, patiently awaiting rebirth. We strike now at our enemy with the awakened strength of the Scourge!\n\nThe ghouls have already begun their assault upon New Avalon. Our forces have moved in behind them and taken the Crypt of Remembrance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12715] = { id = 12715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crypt of Remembrance", description = "The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls are wearing the Crusade's front lines down while we labor to fortify our new forward base, the Crypt of Remembrance.\n\nVenture south to the crypt, which borders New Avalon, and report to my dear brother, Prince Keleseth.\n\nHe will be expecting you.\n\nPrepare yourself, {name}, for you are about to witness the next stage of Scourge warfare: DOMINATION!\n\nRide now, death knight!", sourceObjective = "Report to Prince Keleseth at the Crypt of Remembrance.", completion = "Hail, {class}. I am the blood lord, Keleseth, ruler of the southeastern reaches of Northrend. The Lich King has sought to utilize my talents in ending this mortal affront to the Scourge. As with all things the Lich King asks of me, I am happy to oblige. Of course, a sea of endless souls to sate my thirst certainly sweetened the deal, don't you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[12716] = { id = 12716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plaguebringer's Request", description = "Look at this pumpkin patch! Notice anything missing? Of course you don't, because you're a moron! Your brain was probably the first thing to die.\n\n<Noth sighs.>\n\nI have been commanded to put together a plague cauldron. You will help me.\n\nDirectly inside the gate of New Avalon is the inn. Enter the inn and steal an empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get those too?", sourceObjective = "Noth the Plaguebringer has requested that you bring him 1 Empty Cauldron, 1 Iron Chain and 10 Crusader Skulls.", progress = "Have you gathered the materials I requested?", completion = "Perfect! Now give me a moment to get things set up.", sourceObjectiveStatus = "unverified-source-field" }
quests[12717] = { id = 12717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth's Special Brew", description = "The cauldron is ready to begin spewing its foul corruption across the land!\n\nNow, death knight, a brief lesson in plague cauldrons. The gas that the cauldron emits is deadly to the living, but empowers Scourge. As with all Scourge creations, it feeds off of death and grows stronger the longer it feeds.\n\nTake these Crusader skulls and drop them in the cauldron. You will be quite happy with the results.", sourceObjective = "Place the Pile of Crusader Skulls inside the Plague Cauldron.", progress = "The plague cauldron stands idle.", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds some vials of dark liquid float to the top.", sourceObjectiveStatus = "unverified-source-field" }
quests[12718] = { id = 12718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Skulls For Brew", progress = "The plague cauldron bubbles and churns its toxic brew, spewing a thick gas all around.\n\nDo you have more Crusader skulls to place inside?", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds, the plague cauldron grants you the dark and frothy splendor of Noth's Special Brew." }
quests[12719] = { id = 12719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere To Run And Nowhere To Hide", description = "Nothing less than total annihilation will suffice, {name}. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge's grasp!\n\nMake your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.", sourceObjective = "Prince Keleseth at the Crypt of Remembrance has ordered you to kill Mayor Quimby and recover the New Avalon Registry.", progress = "There is nowhere to run!", completion = "The registry will tell us many things about the Scarlet insects.\n\n<Keleseth flips through the pages of the registry.>\n\nDeath rates, births, but most importantly, movement.\n\nLook here, {name}, they have already sent three vessels abroad. Let me see here... Where are they headed?\n\n\n\nWHAT? This is impossible. They sail to Northrend!\n\nBeside the coordinates are the words: \"Crimson Dawn.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[12720] = { id = 12720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How To Win Friends And Influence Enemies", description = "In my travels across this world I have made several interesting discoveries. For instance, did you know that with the proper amount of encouragement one can extract all the truths that a man dares hide? As luck would have it, I happen to have some encouragement on hand.\n\n<Keleseth pulls something out of an ornately jeweled box.>\n\nThese are my \"persuaders.\" Equip them and take to the field, death knight. Apply the pointy ends to the soldiers of New Avalon. Discover the truth about this \"Crimson Dawn.\"", sourceObjective = "Prince Keleseth at the Crypt of Remembrance has ordered you to discover the truth about the \"Crimson Dawn.\"\n\nRemove Keleseth's Persuaders from the Ornately Jeweled Box and use them to \"persuade\" the Scarlet Crusade into talking.", progress = "Use the persuaders on Scarlet Crusaders. One of them will eventually... crack.", completion = "An awakening? What nonsense do you speak, boy! What kind of fool would deliver their people into the very heart of the frozen wastes? Perhaps, though, this courier holds the answer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12721] = { id = 12721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampage", description = "{name}, there is no time left. You must take the key and use it to unlock Akali.\n\nHe is being held in the courtyard in front of Gundrak, the capital of Zul'Drak. Akali's chains are secured by four anchor points. You must unlock each of them to set the rhino god free.\n\nGundrak is teeming with ice trolls. However, I believe that if you're careful, you should be able to slip in without too much danger.\n\nOnce you're done, please inform the witch doctor.", sourceObjective = "Har'koa at Zim'Torga has asked you to free Akali and then to inform Witch Doctor Khufu at Zim'Torga.", progress = "What happened?", completion = "No!\n\nAnother god destroyed, its power stolen. And now the prophet of Akali has threatened us directly.\n\nWhen he comes, he will come for Har'koa. We cannot allow him to take her power too.\n\nWe must consult the gods once more, {name}. They will tell us what must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[12722] = { id = 12722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lambs To The Slaughter", description = "Most humans would have fled the moment a Scourge necropolis took up residence in their air space. Not the Scarlet Crusade!\n\nI must confess - I rather enjoy our exchanges with the Crusade. Through the years, Scourge battles against them have resulted in several of the most tragic events in human history. Yet here we stand - AGAIN - locked in battle!\n\nWe shan't deny them the pleasures of eternal servitude to the Lich King! Enter New Avalon and fulfill their death wish. Leave no survivors.", sourceObjective = "Baron Rivendare at the Crypt of Remembrance has commanded you to slay 10 Scarlet Crusade Soldiers and 15 Citizens of New Avalon.", completion = "You are quite effective with that blade, {name}. Perhaps, Lich King permitting, you would be interested in becoming one of my minions? Stratholme is looking for a new mayor.", sourceObjectiveStatus = "unverified-source-field" }
quests[12723] = { id = 12723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Scarlet Lines", description = "I have sent Orbaz, Thassarian and Koltira behind enemy lines to search for the courier. They have set up a base of operations at the Scarlet Tavern, located at the southern end of New Avalon. The tavern is tucked away behind the two orchards, adjacent to the Chapel of the Crimson Flame. You are to make your way to the tavern and report to Orbaz Bloodbane. He will update you on their situation.", sourceObjective = "Report to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.", completion = "Looks like we'll let anyone into the dark order these days. When I was given the gift, things were different. Much different!\n\nAs to this courier...", sourceObjectiveStatus = "unverified-source-field" }
quests[12724] = { id = 12724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Of The Righteous Crusader", description = "We haven't got a damned clue about when or where this courier is supposed to show up. None of these humans had an answer either.\n\n<Orbaz points to the Scarlet corpses strewn across the floor.>\n\nI did manage to beat something useful out of the last one. Inside Scarlet Hold they keep a schedule of all patrol routes. I want you to break into the hold and steal the schedule.\n\nThe hold is the largest building in New Avalon - northeast of here.", sourceObjective = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to steal the New Avalon Patrol Schedule from the Scarlet Hold.", progress = "Tear the hold apart! The schedule is there!", completion = "<Orbaz flips through the schedule.>\n\nThese worthless cretins have been busy! Northern patrol routes, southern patrol routes, western patrol routes, eastern patrol routes, but nothing about their couriers' routes. Wait a minute. What's this? It looks like a western patrol route, coming out of Western Plaguelands? This patrol will path through here today! I'm going to need time to plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[12725] = { id = 12725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brothers In Death", description = "Breaking through the Scarlet lines was no easy task. We suffered many casualties during the assault and lost one of our best death knights, Koltira Deathweaver. I don't know whether he's dead or alive, but I'll be damned if we don't search for him.\n\nI last saw him being bound in irons and dragged away to the Scarlet Hold, northeast of here. Tear that keep asunder, death knight. Find Koltira!", sourceObjective = "Search for Koltira Deathweaver in the Scarlet Hold.", completion = "You were foolish in coming after me. I failed. I should have been left for dead - now two of us might be killed.\n\n<Koltira shakes his head.>\n\nWe are death knights of the Scourge. This flies in the face of the dark brotherhood's covenants.\n\nThassarian, you blasted fool!", sourceObjectiveStatus = "unverified-source-field" }
quests[12726] = { id = 12726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Wind and Water", description = "Listen to storm, yes?  The Stormwright's Shelf echoes with ancient song.... the Song of Wind and Water.\n\nThe great tempest devours the sons of typhoons and storms.  Take this drum and play his song... play Haiphoon's song.\n\nHelp him feed on wind and water so tempest can continue.", sourceObjective = "Soo-nee wants you to use the Tempest Drums at the Stormwright's Shelf and help Haiphoon devour 3 Storm Revenants and 3 Aqueous Spirits.", completion = "I thank you, {name}.  The great tempest will look upon us favorably thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12727] = { id = 12727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Breakout", description = "The alarms have been sounded. The High Inquisitor and his acolytes will be here soon. I'm too badly injured to be of much use, but I'll do what little I can to help.\n\nSlay the High Inquisitor and his cronies. Tear off his head and return with it to Thassarian. Vengeance will soothe his savage soul.\n\nOne more thing, {name}. If you do manage to survive and make it back to Thassarian, tell him that they're executing prisoners at the chapel. Perhaps he'll send you there to play the hero once more.", sourceObjective = "Slay High Inquisitor Valroth and take Valroth's Head to Thassarian at the Scarlet Tavern in New Avalon.", progress = "What of Koltira?", completion = "I'll feed this monster's head to the ghouls!\n\n<Thassarian tosses the head into the back room.>\n\nDid Koltira make it out?\n\n<Thassarian pauses.>\n\nI'm certain he did. Those walls can't hold him.\n\nTime for some payback.", sourceObjectiveStatus = "unverified-source-field" }
quests[12728] = { id = 12728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring the Rift: Winterfin Cavern", description = "I need to compile my notes and prepare a presentation for my colleagues in Dalaran.\n\nWhile I do, I must ask that you visit the Winterfin Cavern to the north. You must use the Arcanometer while standing in the mouth of the cavern.\n\nReturn to me at once when you have the data. My documentation will be incomplete without it.", sourceObjective = "Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.", progress = "Have you collected the data from Winterfin Caverns yet, {name}?", completion = "Excellent, this completes my report.\n\nI'll be sure to mention your kindness to the council, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12729] = { id = 12729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gods Have Spoken", description = "The gods have spoken and we must heed their wisdom.\n\nTravel north to Zim'Rhuk to destroy guardians there until they yield the unblemished heart. Travel east to the Altar of Quetz'lun and disrupt the altar wardens until you recover their gusty essence.\n\nDeliver both to Har'koa and she will combine them into that which will compel late Akali's prophet to appear.", sourceObjective = "Deliver the Unblemished Heart of the Guardian and the Gusty Essence of the Warden to Har'koa at Zim'Torga.", progress = "Do you have that which is required, {name}?", completion = "Your bravery seems boundless, {name}.\n\nPlease hand me the heart and the essence, and I will fashion them into that which will compel the prophet to appear before you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12730] = { id = 12730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convocation at Zol'Heb", description = "You must take this instrument of convocation - of summoning - to Zol'Heb just south of Gundrak.\n\nTherein you will find a circle of power. Use the convocation to force the prophet of Akali to appear.\n\nMy heart goes out to you, {name}. We have been through much together, and you have done all that you can to not only save my life, but those of the other gods the Drakkari have destroyed.\n\nBut I fear this time we may not see each other again until the afterlife.", sourceObjective = "Har'koa at Zim'Torga has asked you to slay the Prophet of Akali.", progress = "I can only offer you the warmth of my words and the encouragement that comes with them.\n\nTake what time you need to steel and prepare yourself, but I implore you not to take too long or the prophet will surely descend upon us.", completion = "You did it! {name}, you are the champion of Zul'Drak!\n\nWe will never be able to repay the debt that we owe to you, but the Zandalari have given into my trust a number of objects they believe you might have an interest in.\n\nPlease, I want you to have a token of our appreciation, but hurry. I sense another issue of urgency!", sourceObjectiveStatus = "unverified-source-field" }
quests[12732] = { id = 12732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heartblood's Strength", description = "One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek strong. You see soon.\n\nRejek give you vial, you take to very top of Suntouched Pillar, far to west. Put waters there in vial.\n\nThen go to north edge of basin, to ledge north of Bonefields. You find and kill goretalon matriarch. Take heartblood.\n\nYou combine heartblood and water, bring to Rejek. Rejek drink, make strong.", sourceObjective = "Bring a vial of Suntouched Heartblood to Rejek at Frenzyheart Hill.", progress = "You bring Rejek gift?", completion = "Rejek thanks you. Rejek drink, grow strong, always remember mighty {name}'s gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[12733] = { id = 12733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Challenge", description = "Born of the Lich King's victory over Illidan Stormrage in the heart of the frozen wastes, Death's Challenge is a rite of passage that all death knights must undergo.\n\nSeek out other death knights of Acherus and challenge them to a duel. They must accept and fight until a victor emerges!\n\nGo now, {name}! Victory for the Scourge! Glory to the Lich King!", sourceObjective = "Olrun the Battlecaller has ordered you to win 5 duels against other death knights.\n\nYou may choose to battle death knight initiates or players.", progress = "Have you completed Death's Challenge?", completion = "To the victor goes the glory, {class}! Well done! The Lich King looks favorably upon you on this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[12734] = { id = 12734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejek: First Blood", description = "Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to be blooded first. Older warrior usually do that. You do this honor for Rejek?\n\nTake blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide Lake.", sourceObjective = "Blood Rejek's Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete.", progress = "You blood Rejek's blade?", completion = "Rejek sees the stains of the blood of his enemies on the blade. Now Rejek has a mighty weapon for the mighty warrior he will be!", sourceObjectiveStatus = "unverified-source-field" }
quests[12735] = { id = 12735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cleansing Song", description = "Earth in Sholazar is pure.  The pillars have protected the land for centuries.\n\nWater, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed.\n\nYou take this chime and play at Bittertide Lake, Wintergrasp River and River's Heart.  It make bad spirit angry... and then you must kill it.", sourceObjective = "Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart and slay the evil spirits that plague the waters there.", progress = "You play cleansing song yet, {name}?", completion = "Waters... cleansed.  Yes.  All is well.\n\nYou understand our way, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12736] = { id = 12736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Reflection", description = "Of course you not as smart as gorloc!  You just simple {race}.\n\nYou not without hope, though!  You show you can learn.  Maybe crystals make you smart like crystals make us smart!\n\nI teach you to play song to clear your mind.  You play song by crystals then crystals make your mind better... not as good as gorloc's but better than you have now.  Lifeblood Pillar is broken, but other pillars still good!", sourceObjective = "Soo-nee at Rainspeaker Canopy wants you to use the Didgeridoo of Contemplation at the top of the Glimmering Pillar, the Suntouched Pillar, the Mosslight Pillar and the Skyreach Pillar.", progress = "You feel smart yet, {race}?", completion = "You see?  I can tell you smarter already.  And if not smarter... then... happier!", sourceObjectiveStatus = "unverified-source-field" }
quests[12737] = { id = 12737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Fecundity", description = "The storm is a destructive force.  Storm burns trees.  Storm floods houses.\n\nBut storm can also be life force if you know right song.  In Stormwright Shelf, above Maker's Perch, you can find small dirt mounds.  They very fertile -- they carry inside a strong seed.  All they wait for is the right song.\n\nYou take this horn and play song for them.", sourceObjective = "Soo-nee at Rainspeaker Canopy wants you to go to the Stormwright's Shelf, northwest of the Maker's Perch, and play the Horn of Fecundity near 8 piles Soaked Fertile Dirt.", completion = "You learn fast, {name}.  You learn that song well.  Maybe next time I teach you different song.", sourceObjectiveStatus = "unverified-source-field" }
quests[12738] = { id = 12738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry For Vengeance!", description = "The cry for vengeance must be heard, {name}. Commander Plaguefist and a company of death knights are on their way to raze the Chapel of the Crimson Flame. If there are any death knights imprisoned at the chapel, Plaguefist will get them out.\n\nYou can still catch up to them if you hurry. The chapel is due west of here.", sourceObjective = "Report to Knight Commander Plaguefist at the Chapel of the Crimson Flame.", completion = "They're only flesh and bone - no match for the Scourge.\n\nWe didn't find any of our brothers, but we did stumble upon something special.", sourceObjectiveStatus = "unverified-source-field" }
quests[12739] = { id = 12739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty tauren in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Malar Bravehorn, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12740] = { id = 12740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parachutes for the Argent Crusade", description = "Those sky terrors are destroying my men and women! Dying from falling is a horrible way to go.\n\n{class}, you have to get these parachutes out to them! At least then they'll have a fighting chance to survive.", sourceObjective = "Commander Falstaav at The Argent Stand has asked you to equip 10 Argent Crusaders or Argent Shieldmen out in the courtyard with parachutes.", progress = "If you're back here talking to me why do I still see my people falling to their deaths?", completion = "You're a good man, {name}. We're fortunate that you happened to stop by.\n\nStick around a while. I'm sure that we have much that a capable {class} such as yourself can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[12741] = { id = 12741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of the Tempest", description = "Silly big-tongues think singing to the clouds give them power. Rejek show big-tongues how to get power by taking it!\n\nFar to northwest, there is large, flat area the big-tongues call 'Stormwright's Shelf.' Rejek is sure you can only get there by flying like bird.\n\nOn this shelf, Rejek has heard of mighty forces of wind and water. Kill them for their badness, then take it to the big-tongue 'Shrine of the Tempest' at shelf's western side. Rejek will await your return with ultimate power.", sourceObjective = "Gather 3 Essences of the Monsoon and 3 Essences of the Storm and take them to the Shrine of the Tempest. Return to Rejek at Frenzyheart Hill with the True Power of the Tempest.", progress = "You bring Rejek true power of elements?", completion = "Now Rejek show cowardly big-tongues how to really use elements!", sourceObjectiveStatus = "unverified-source-field" }
quests[12742] = { id = 12742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty human in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Ellen Stanbridge, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12743] = { id = 12743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty night elf in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Yazmina Oakenthorn, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12744] = { id = 12744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty dwarf in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Donovan Pulfrost, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12745] = { id = 12745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty gnome in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Goby Blastenheimer, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12746] = { id = 12746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty draenei in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Valok the Righteous, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12747] = { id = 12747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty blood elf in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Lady Eonys, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12748] = { id = 12748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty orc in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Kug Ironjaw, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12749] = { id = 12749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty troll in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Iggy Darktusk, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12750] = { id = 12750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty Forsaken in there that I think you'll take great pleasure in executing.", sourceObjective = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Antoine Brack, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", sourceObjectiveStatus = "unverified-source-field" }
quests[12751] = { id = 12751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sort Of Homecoming", description = "Return to Thassarian at the Scarlet Tavern and let him know that Koltira's cry for vengeance has been answered. The Chapel of the Crimson Flame will be a pile of ashes in a matter of hours.\n\nYou're one cold-blooded monster, {name}. I salute you, <brother/sister>.", sourceObjective = "Return to Thassarian at the Scarlet Tavern in New Avalon with news of your victory.", completion = "Another Scourge victory! These Scarlet dogs have nowhere left to run and hide. It's only a matter of time now...", sourceObjectiveStatus = "unverified-source-field" }
quests[12752] = { id = 12752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "Greetings, brother.  You may have come on behalf of the Argent Dawn, but that is not why you are here -- you are here to help your people earn the respect we so justly deserve.  As any forsaken will agree, the end justifies the means, and our research into the zombie plague's cure is that proverb in practice...", sourceObjectiveStatus = "unverified-source-field" }
quests[12753] = { id = 12753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "Brother {race}, I am proud to stand with you during our days of need.  Bless you, and may the alliance between {race} and human last a thousand years.", sourceObjectiveStatus = "unverified-source-field" }
quests[12754] = { id = 12754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambush At The Overlook", description = "While you were out burning churches and murdering vermin, I've been busy formulating a plan.\n\nThe Scarlet courier is scheduled to pass by the Scarlet Overlook within the hour. The roads by the overlook are wide open and swarming with Crusaders. Use this makeshift cover to hide at the overlook and wait for the Scarlet Courier to pass. When he's close enough, strike with all your fury! Cut him down and take his belongings - including his clothes!\n\nThe overlook is 200 paces east of here.", sourceObjective = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to kill the Scarlet Courier and retrieve the Scarlet Courier's Belongings and the Scarlet Courier's Message.", progress = "You're going to miss the courier and then I'm going to be forced to kill you. By forced I mean I will take great pleasure in ending your life.\n\nHURRY UP!", completion = "<Orbaz reads the message.>\n\nThe armies of Hearthglen and Tirisfal will be marching into a massacre.\n\n<Orbaz smiles.>\n\nNow for the second part of the plan. You're going to deliver this message right into the hands of High General Abbendis. That's what the clothes are for...", sourceObjectiveStatus = "unverified-source-field" }
quests[12755] = { id = 12755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meeting With Fate", description = "This message must reach Abbendis. We do not want to draw their suspicion. They must continue under the assumption that everything is going as they planned.\n\nYou will don the Scarlet courier's clothes and with the help of some dark magic, take on the form of the courier.\n\nAbbendis is at King's Harbor, southeast of the Scarlet Overlook. Drop off the message and get as much information out of her as you can. She will tell us what we need to know about the \"Crimson Dawn.\"", sourceObjective = "Orbaz Bloodbane has commanded you to deliver the Scarlet Courier's Message to High General Abbendis at King's Harbor.", progress = "Where have you been? You are two hours late. We were about to send a courier out to the High Commander.", completion = "<High General Abbendis reads the message.>\n\nDamn it! The armies of Hearthglen and Tirisfal must not reach New Avalon! The Scourge will slaughter them all.", sourceObjectiveStatus = "unverified-source-field" }
quests[12756] = { id = 12756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Onslaught Emerges", description = "Listen well, courier. The Scarlet lands are lost. New Avalon and Havenshire are overrun by Scourge. The specter of death looms overhead and threatens to overtake us at any moment.\n\nReturn to Galvar with this message:\n\n\"Turn your armies around and prepare your ships for travel to the frozen wastes. When next we meet it will be in Northrend.\"\n\nGive this to Galvar.\n\n<Abbendis hands you a journal.>\n\nIt will explain everything.\n\nThe Scarlet Crusade is no more. Long live the Scarlet Onslaught!", sourceObjective = "Deliver The Path of Redemption to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.", progress = "<Orbaz laughs.>\n\nWhat is this? Some child's coloring book?", completion = "<Orbaz flips through the journal.>\n\nWhat rubbish! This is the \"Crimson Dawn?\"\n\nThey sail to their deaths! Let us turn our focus to the encroaching armies.", sourceObjectiveStatus = "unverified-source-field" }
quests[12757] = { id = 12757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Armies Approach...", description = "We must prepare for the encroaching armies, {name}. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you.\n\nGive Highlord Mograine Abbendis' journal as well. Perhaps he'll find it useful.", sourceObjective = "Deliver The Path of Redemption to Highlord Darion Mograine at Acherus: The Ebon Hold.", progress = "You did what?", completion = "You have become an instrument of doom, {class}! We will ravage these approaching armies and raise the dead as our own!", sourceObjectiveStatus = "unverified-source-field" }
quests[12758] = { id = 12758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Headgear", description = "Rejek hears tales of giant metal men on faraway Stormwright's Shelf. Far to northwest, outside basin's lip, you will find it.\n\nImagine Rejek using heads of giant metal men as helmet. Make Rejek unstoppable! Make Rejek mighty!\n\nYou get for Rejek, but metal head might not come off metal body easy. Maybe steal bombs from little green men and their friends at Swindlegrin's Dig near Suntouched Pillar? Use bombs to get head off metal body, then bring to Rejek.", sourceObjective = "Get Venture Co. Explosives from any of the Venture Company units at Swindlegrin's Dig and use them to obtain a Stormwatcher's Head. Bring the Stomwatcher's Head to Rejek at Frenzyheart Hill.", progress = "You bring Rejek's new helmet?", completion = "Rejek sees you were successful! Now Rejek try on new war helmet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12759] = { id = 12759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of War", description = "Zepik tell me that you maybe the best gorloc hunter he met... other than Zepik. Still big battle to southwest - you go help.\n\nZepik keeps some of biggest, baddest traps in his stash at Kartak's Hold... told Vekgar to use them for battle, so you use them too. Go pick out any traps you want and kill lots of big-tongues.\n\nLots and lots!", sourceObjective = "Retrieve some of Zepik's traps from his stash in Kartak's Hold. Using the traps, slaughter 50 of the nearby Sparktouched Gorlocs, and then return to Shaman Jakjek in Kartak's Hold.", progress = "Kind of messy! But still so fun.", completion = "You almost as good with those traps as Zepik!", sourceObjectiveStatus = "unverified-source-field" }
quests[12760] = { id = 12760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Strength of the Frenzyheart", description = "Battle still going at Kartak hold... I think it time for you to learn big secret of Frenzyheart.\n\nWe have berries we keep from other lands we came from... they not so special on their own, but mix them with drunk drinks and they make Frenzyheart super strong. You a Frenzyheart now... it time you get to be strong too.\n\nI give some drink, then you be super strong and you go smash all the spark big-tongues.", sourceObjective = "Using the secret Frenzyheart drink, slaughter 30 of the Sparktouched Gorlocs around Kartak's Hold.", completion = "You a fierce fighter... come back for more battle soon. Never enough good battle!", sourceObjectiveStatus = "unverified-source-field" }
quests[12761] = { id = 12761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastery of the Crystals", description = "Sparktouched are still being attacked by puppy-men... we think they maybe not stop if we not make them stop. We have secret weapon though... we sent it out to Soo-met so he can use to protect all Oracles.\n\nSecret weapon is from Great Ones themselves... extra shiny crystals found inside sacred Great One temples. Be very careful... no break them.\n\nCrystals are in chest near shrine at Sparktouched Haven, in far southwest. You go use crystals to help Soo-met beat the puppy-men.", sourceObjective = "Retrieve the crystal defenses at Sparktouched Haven and use them to kill 50 of the nearby Frenzyheart wolvar. When these tasks are complete, return to Lightningcaller Soo-met in Sparktouched Haven.", progress = "Very powerful. Puppy-men not know about power of Great Ones. Dumb puppy-men.", completion = "Thank you, dryskin.\n\nI hold onto these crystals here to keep us safe. Maybe you come back soon and help us more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12762] = { id = 12762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Great Ones", description = "We need to do something to stop puppy-men attacking Sparktouched Haven. Jaloot brought me very special crystal that he found in River's Heart... we seen only one like it before.\n\nThe crystal not have power now, but the opened up lifeblood pillar should have energy to recharge it if you just bring it close. Once the crystal is charged, go to Sparktouched Haven in far southwest and let the crystal's energy make you big and strong.\n\nThen it time to kick some puppy-men butt.", sourceObjective = "Charge the Dormant Polished Crystal at the exposed Lifeblood Pillar. Travel to Sparktouched Haven and use the power the crystal bestows to slaughter 30 of the nearby Frenzyheart wolvar, and then speak to Lightningcaller Soo-met in Sparktouched Haven.", progress = "Good to have you here to help us. Long fight.", completion = "So much energy in you... you full of the power of the Great Ones!\n\n I not lie, I little bit jealous.", sourceObjectiveStatus = "unverified-source-field" }
quests[12763] = { id = 12763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shifting Priorities", description = "As pressing as our needs are here, there's news from the lands to the north that cannot be ignored.\n\nI've just received a message from the Argent Crusade. It seems that scourge forces are gathering there and are threatening to overrun Zul'drak.\n\nNeedless to say, {name}, if that were to happen our struggle here would be meaningless. You must go there and aid the Crusaders in beating back the Lich King's armies.\n\nSpeak to Makki when you are ready to travel.", sourceObjective = "Scout Vor'takh wants you to travel to Zul'Drak and report to Sergeant Riannah at Light's Breach.\n\nMakki Wintergale in Camp Oneqwah will provide you transportation.", completion = "The Light shall prevail!", sourceObjectiveStatus = "unverified-source-field" }
quests[12766] = { id = 12766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nShe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", sourceObjective = "Speak with Lauriel Trueblade at Wyrmrest Temple.", completion = "You must be {name}. I was told you'd be coming.\n\nI have something that I think you're uniquely qualified to take care of and by doing it, you'll be ingratiating yourself with the dragons here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12767] = { id = 12767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nHe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", sourceObjective = "Speak with Golluck Rockfist at Wyrmrest Temple.", completion = "You must be {name}. I was told you'd be coming.\n\n\n\nI have something that I want you to take care of. If you do, you'll prove yourself to the dragons here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12768] = { id = 12768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", sourceObjective = "Speak with Tariolstrasz at Wyrmrest Temple.", completion = "Back so soon, {name}?\n\nCeristrasz sent word ahead of you. Thank you for what you did at the Ruby Dragonshrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[12769] = { id = 12769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", sourceObjective = "Speak with Tariolstrasz at Wyrmrest Temple.", completion = "Back so soon, {name}?\n\nVargastrasz sent word ahead of you. Thank you for what you did at the Ruby Dragonshrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[12770] = { id = 12770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reallocating Resources", description = "Listen up, {class}!\n\nYour days here are numbered. As much as we need capable {class}s in our ranks, there's trouble up north that makes our problems look like a mid-summer Stormwind parade.\n\nTurns out the Scourge are concentrating their efforts - making a big push to take over Zul'Drak. If that happens, we may as well pack it in.\n\nYou're free to finish any business here, but then it's off to Light's Breach with you. Speak to Samuel if you need transportation.\n\nDismissed.", sourceObjective = "Gryan Stoutmantle wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak.\n\nYou may speak to Samuel Clearbook for transportation to Light's Breach.", completion = "The Light shall prevail!", sourceObjectiveStatus = "unverified-source-field" }
quests[12771] = { id = 12771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  Magni Bronzebeard is eager to take the fight to Northrend, and this will bring him closer to his goal.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to King Magni Bronzebeard in Ironforge.", progress = "Hello, {name}.  A stouter {race} I never did see!  The trials of Outland have made you tough, brother.  You do your race proud!", completion = "By my beard!  This holds a power to rival a fleet of our flying machines!  I'll give it to my war priests and we'll devise a plan to send those vile necropolises scurrying back to Northrend... and we'll be right behind them!\n\nOh, Muradin my brother, you must live!  By the honor of the Bronzebeards, I will find you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12772] = { id = 12772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "{name}, honorable {race}, welcome.  May the Light shine upon you, and may your ancient wisdom ward our land in its time of need.", sourceObjectiveStatus = "unverified-source-field" }
quests[12773] = { id = 12773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Darnassus.  Deliver it to Tyrande Whisperwind -- her priests will find it a vital source of power in their fight against the unholy forces from the North.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to Tyrande Whisperwind in Darnassus.", progress = "{name}, my son.  Once again we are pulled into a conflict that may sunder all we know.  It is good to have a {class} of your talents lend his strength to this world tree's defense.", completion = "What is this?  What a boon!  They have captured such Light into this artifact, it shines nigh bright as the moon!  Our priests will channel this power against our foes, and the Lich King's invasion will surely fail.  Thank you, {name}.  Our world tree will be safe.\n\nWhat's more, we have sensed that perhaps another world tree grows far to the north, nestled hidden near the Lich King's own domain.  Perhaps someday... we will shepherd both trees and herald a new era of peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[12774] = { id = 12774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Stormwind.  The King of Stormwind has recently returned; I'm sure he will welcome this tool.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to King Varian Wrynn in Stormwind.", progress = "{name}, it's good to see you.  Your strength and skills are a boon during this time of tribulations.", completion = "So, the holy folk in Shattrath created what they promised!  In hindsight, diverting so many priests and paladins there, instead of sending them against the Scourge, was the right move.  With this holy weapon,  we can beat back that damned Lich King and his minions!\n\nI commend you, Lord {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12775] = { id = 12775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "Brother, we are called again to fight against the Scourge.  It is good you are here; with your strength, and the power of the Light, we may yet prevail.", sourceObjectiveStatus = "unverified-source-field" }
quests[12776] = { id = 12776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exodar", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to the Exodar.  Deliver it to Prophet Velen in the Vault of Lights so that he may use its powers against the unholy forces from the North.", sourceObjective = "Bishop Lazaril wants you to deliver the Light-infused Artifact to Velen in the Exodar.", progress = "My son, the lands of the humans and orcs have treated you well.  Such strength now swells within you...", completion = "Ah, I can see the power of the Naaru shine through this thing, as if Light itself is housed here.  Such good can be done with this implement; the necropolises sent from the frozen wastes of the north will surely fail.", sourceObjectiveStatus = "unverified-source-field" }
quests[12777] = { id = 12777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "My heart swells with Light to see you, a noble {race}, come to our aid.  Bless you, good {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12778] = { id = 12778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Apocalypse", description = "The trap has been sprung, death knight. The armies of Hearthglen and Tirisfal have arrived, just in time to see their enclave in flames! If they turn back now, they fight us with their backs turned.\n\n<Mograine shakes his head.>\n\nNo, they have only one option, which has only one outcome: APOCALYPSE!\n\nAs we speak, they prepare to make one final stand.\n\nThe Lich King awaits your return, champion. He stands watch below us, at Death's Breach.", sourceObjective = "Seek out the Lich King at Death's Breach.", completion = "You have served me well, {name}. The mark of the Scourge has been burned into these Scarlet lands. You have reaped death and destruction for as far as the eye can see and delivered to me the last of the Scarlet armies.\n\n\n\nIt is now time to finish what you started.", sourceObjectiveStatus = "unverified-source-field" }
quests[12779] = { id = 12779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End To All Things...", description = "You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, {name}.\n\n<The Lich King pauses.>\n\nThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.\n\nUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.", sourceObjective = "The Lich King has commanded you to eradicate the Scarlet Crusade.\n\nUse the Horn of the Frostbrood to call forth a Frostbrood Vanquisher and with it slay 150 Scarlet Soldiers and destroy 10 Scarlet Ballistas. Avoid incoming projectiles by moving out of their line of fire!", progress = "Kill them all...", completion = "Kneel, champion. I place this helm upon your head to complete your terrifying visage. Any that dare look upon your dark countenance will know that death comes. Let none stand so boldly against your king so as to face your merciless wrath, {name}.\n\nThere remains only one final task...\n\n\n\nLight's Hope Chapel.", sourceObjectiveStatus = "unverified-source-field" }
quests[12780] = { id = 12780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEPRICATED>>Enemy of Our Enemy", description = "As much as we find working with death knights distasteful, we cannot afford to be picky about our allies here.\n\nWe're pinched between the Scourge and the savage Drakkari, who want nothing more than to destroy us so that they can get at one another.\n\nTravel west to Ebon Watch. Speak with Stefan and see if you can be of service to him.", sourceObjective = "Sergeant Riannah in Light's Breach wants you to speak with Stefan in Ebon Watch and offer your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12781] = { id = 12781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Siouxsie the Banshee in Ebon Hold.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!You will be able to choose one of these rewards:", sourceObjective = "Bring the Ebon Hold Gift Voucher to Siouxsie the Banshee in Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[12782] = { id = 12782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  So, elf, as your race's self-proclaimed name implies... Do you have blood to spare?  Fresh blood is welcome blood indeed...", sourceObjectiveStatus = "unverified-source-field" }
quests[12783] = { id = 12783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine, robust specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  Fresh blood is welcome blood indeed, and the rage in your blood could fuel hours of research.", sourceObjectiveStatus = "unverified-source-field" }
quests[12784] = { id = 12784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine, robust specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  Fresh blood is welcome blood indeed, and I'm sure someone of your stature has blood to spare...", sourceObjectiveStatus = "unverified-source-field" }
quests[12785] = { id = 12785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given us new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Warchief Thrall in Orgrimmar.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.", progress = "Welcome to Orgrimmar, {name}.  Grand Apothecary Putress sent word ahead of you... do you have the infected brain?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12786] = { id = 12786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Bluff", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Thunder Bluff.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Chaney.  He attends Magatha Grimtotem in Thunder Bluff.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Chaney in Thunder Bluff.", progress = "Welcome to Thunder Bluff, {name}.  Grand Apothecary Putress sent word ahead of you... do you have the infected brain?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12787] = { id = 12787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Undercity", description = "The zombie plague was a blessing in disguise.  In our search for a cure, we have learned so much of the Scourge and their contagion.  Our research has given us weapons against them.  Weapons, and tools...\n\nTake this -- it is a zombie's head and has been partially cured of its plague by injecting it with a compound derived from our recent discoveries.  Deliver the head to Master Apothecary Faranell; I have a list of experiments I would like him to perform on it.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Master Apothecary Faranell in the Undercity.", progress = "Salutations, {name}.  You come from Shattrath?  You have instructions from Grand Apothecary Putress?", completion = "Ah, what a fine specimen you are.  The disease, -- diseases -- dancing through your brain must offer you visions so sublime.  We will spend long nights in conversation, you and I, and I will pick from you your thoughts as I slowly extract the meat from your skull.\n\nDo not fear, little one.  The knowledge gained from your sacrifice will be awesome.  You are a gift to the forsaken; you will herald a new age of respect for us among the peoples of this world.  Your place in our history is assured...", sourceObjectiveStatus = "unverified-source-field" }
quests[12788] = { id = 12788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermoon", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Silvermoon City.  Inside is a head that is infected with the zombie plague, and something else... an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Tepesh.  She attends Lor'themar Theron in Silvermoon City.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Tepesh in Silvermoon City.", progress = "Welcome to Silvermoon, {name}.  Grand Apothecary Putress sent word ahead of you... do you have the infected brain?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12789] = { id = 12789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Breach!", description = "Ready yourself, {class}. I'm dispatching you to Light's Breach, northeast of here.\n\nI've received word that the Scourge are making a push to take over Zul'Drak.\n\n<Valus stares you dead in the eyes.>\n\nThis will not come to pass.\n\nSee to it that you assist in the destruction of the Scourge there. The light demands it.\n\nDismissed.", sourceObjective = "Crusader Valus at Light's Trust wants you to report to Sergeant Riannah at Light's Breach in Zul'Drak.", completion = "Excellent. Valus must have received my report.\n\nLet's get to work, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12790] = { id = 12790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Leave and Return: the Magical Way", description = "Just in case you don't already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran.\n\nCorrespondingly, you can use the crystal at the stand below to return to the chamber above me.\n\nI would like for you to do this now.", sourceObjective = "Archmage Celindra at The Violet Gate in Dalaran wants you to use the Teleport to Violet Stand Crystal and the Teleport to Dalaran Crystal.", progress = "I sense that you haven't yet tested out both of the teleport crystals.\n\nThat's alright, take your time.", completion = "Excellent, {class}. Now you know the way to get down to Crystalsong Forest and also how to return.", sourceObjectiveStatus = "unverified-source-field" }
quests[12791] = { id = 12791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", sourceObjective = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12792] = { id = 12792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Things First", description = "Listen up, {race}!\n\nThis entire region is full of crises. Everywhere you look you'll find those who could use your assistance.\n\n<Kunz looks you squarely in the eye.>\n\nNo one needs your help right now more than Riannah. The scourge have forced their way between us, leaving her and those she commands isolated.\n\nLight's Breach, where her forces are holding out, lies just southwest of here.", sourceObjective = "Commander Kunz at Argent Stand wants you to report to Sergeant Riannah at Light's Breach.", completion = "My report must have made it through to Kunz.\n\nIt is good to know that he is well.", sourceObjectiveStatus = "unverified-source-field" }
quests[12793] = { id = 12793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke on the Horizon", description = "You hear that, {race}?\n\nThe clamor of battle far to the west reaches us here, even over the din of our own struggle.\n\nThe Scourge are threatening to break through the lines of those calling themselves the Argent Crusade. Preventing this is as urgent as anything in the region.\n\nTravel to Light's Breach and join in their struggle. Speak to Maaka and he will provide you safe passage.", sourceObjective = "Khufu in Zim'Torga wants you to travel to Light's Breach and report to Sergeant Riannah there.\n\nMaaka will provide you with transportation there.", completion = "The Light shall prevail!", sourceObjectiveStatus = "unverified-source-field" }
quests[12794] = { id = 12794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", sourceObjective = "Deliver the Kirin Tor Signet to Archmage Celindra at the Violet Gate in Dalaran.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12795] = { id = 12795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Stand", description = "A few moments ago I spotted a signal flare over the treeline to the east.\n\nThat can only mean that things are not going smoothly for the Crusaders at Argent Stand.\n\nI cannot leave our post here, {race}, but you can. When time permits, make your way up to Commander Falstaav and see if there's anything you can do to lighten their burden.", sourceObjective = "Bloodrose Datura at Ebon Watch wants you to speak with Commander Falstaav at The Argent Stand.", completion = "As it happens there is something you can do to be of assistance, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12796] = { id = 12796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", sourceObjective = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran.", progress = "Greetings, {class}.", completion = "Welcome to Dalaran.\n\nI'll see to it that the ring is returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[12797] = { id = 12797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Through the Waygate", description = "You speak the truth, {race}.  I can sense the very essence of Sholazar Basin begin to fray by the blight of undeath even as we speak.\n\nI've bound my being into the rune, {race}.  Deliver it to she who sent you here -- for only her power can grant me passage to her lands.", sourceObjective = "Bring the Omega Rune to the Avatar of Freya at the Rainspeaker Rapids in Sholazar Basin.", progress = "You've returned, {name}.", completion = "You've done well.\n\nWoe unto our enemies.  Woe unto those who serve the Lich King and threaten the titans' creations -- for the Etymidian is here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12798] = { id = 12798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swords Deck", description = "Now that you have gathered all of the Swords cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone.", sourceObjective = "Use the Swords Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to complete a deck of Swords.  Excellent.", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[12799] = { id = 12799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siphoning the Spirits", description = "You should be happy he's coming, they said. You'll enjoy his company, they said....\n\nWell it's not as if I had a choice in the matter. Finklestein is the Crusade's best alchemist. I suppose I should be honored that he's chosen my post to set up shop. But ever since he's arrived, I've been relegated to collecting various alchemical ingredients.\n\nSay, {race}, how about you give me a hand? Just south of here are some pools that are haunted by spirits of ancient trolls. Collect their ectoplasm for me.", sourceObjective = "Captain Arnath at Heb'Valok wants you to collect 5 Ancient Ectoplasms from the Lost Drakkari Spirits at the Pools of Zha'Jin.", progress = "Good day, {race}.\n\nHave you collected the ectoplasm Finklestein asked for?", completion = "Thank you, {class}.\n\nThis should save my men some precious time.", sourceObjectiveStatus = "unverified-source-field" }
quests[12800] = { id = 12800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich King's Command", description = "The Scarlet Enclave is no more. What remains of the Crusade will be dealt with in Northrend.\n\nWe now turn all of our efforts to Light's Hope Chapel. No longer will this affront to your master be allowed to exist!\n\nI have issued my final command. Scourge Commander Thalanor awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the Noxious Glade and take the path leading out of the glade to the mill.\n\nDo not fail me, {name}.", sourceObjective = "Report to Scourge Commander Thalanor at Browman Mill.", completion = "The Highlord and the other death knights are preparing to strike! We will squeeze the last remnants of life out of this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[12801] = { id = 12801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light of Dawn", description = "The Argent Dawn stands defiantly against us at Light's Hope Chapel. They dare oppose the Scourge and for that reason alone they must be destroyed!\n\nThe mighty armies of the Lich King stand at the ready as the final battle for the Plaguelands approaches. Today we ascend into the immortal realm of Scourge heroes!\n\nWhen you are ready for battle, report to Highlord Darion Mograine. It is the highlord who will issue the final march orders and command our armies at Light's Hope Chapel.", sourceObjective = "Defeat the forces of the Argent Dawn and uncover the Light of Dawn.\n\nReport to Highlord Darion Mograine should you survive.", progress = "<Highlord Mograine nods.>", completion = "There will be no atonement for us, {name}. We are forever damned to walk the earth as monsters. While the Lich King may have loosed his grip upon us, the specters of our past will forever haunt our memories.\n\nWe must make amends in the only way we know how: Death...\n\nI ask you now to join me in Acherus as a Knight of the Ebon Blade. Together we will destroy the Lich King and end the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12802] = { id = 12802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Heart is in Your Hands", description = "<Drakuru's voice fills your mind.>\n\nHey, mon! Dis eye of da prophets be great! I been usin' it to watch ya and I see ya got da heart now! Not bad....\n\nNow ya just gotta bring it to my brazier at Drak'atal Passage, a short walk east of ya.\n\nYa must drink my elixir at da pedestal to summon me there. This time, ya need ta mix in some desperate mojo from the defenders there for it ta be workin'.", sourceObjective = "Drakuru wants you to bring the Heart of the Ancients to him at Drak'atal Passage.\n\nYou will need to collect 5 Desperate Mojo to use the elixir there.", completion = "Impressive, mon! Fate be kind in bringin' us together.\n\nSoon I be avengin' me bruddas by cleansin' Drak'Tharon, and you be awarded Drak'Tharon's greatest treasure.", sourceObjectiveStatus = "unverified-source-field" }
quests[12803] = { id = 12803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Force of Nature", description = "I'm not sure about what I saw while flying to the northeast, but to me it looked like a gigantic woman kicking some Scourge butt.\n\nI'd heard the professor talk about a certain \"lifewarden\"  appointed by the titans to look over Sholazar.  I might not be a titan historian, but it sounds like she fits the bill.\n\nI also know that if the Scourge cross the border between the Lost Lands and the rest of Sholazar, our expedition's as good as dead.  What do you say you go look for her and lend a hand?", sourceObjective = "Travel to the Blight Line, between Rainspeaker Rapids and the Lost Lands in Sholazar Basin and seek the Avatar of Freya.", completion = "You are not of this land.  But you also are not with the Scourge.\n\nWhat should I make of you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12804] = { id = 12804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steak Fit for a Hunter", description = "Sometimes, there's nothing worse than a camp full of hunters. They're all so busy taking down prey animals that the only meat I get is tough and stringy. That's hardly the kind of thing you want to come home to after a long day on the hunt.\n\nLucky for us, though, there is a source of tender, succulent meat nearby. To the south of the river and the camp live longneck grazers. They're a perfect source of meat for our hungry hunters. Bring me back the best cuts of meat and we'll properly toast our comrades.", sourceObjective = "Bring 5 Longneck Grazer Steaks to Korg the Cleaver at the Nesingwary Base Camp.", progress = "Did you get those steaks?", completion = "Now that's a meal! If anything good came of the shipwreck, it's got to be that we've been spared eating nothing but salt beef for the next month! Thank you again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12805] = { id = 12805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging Life's Strength", description = "The Lifeblood Pillar was toppled over with great force, sending the very earth into an upheaval.\n\nThe elementals that wander the sundered shard carry with them the very life essence that gave the pillar its strength.  I cannot allow this energy to be wasted, for only four pillars remain.\n\nHead to the sundered shard, to the southeast, and seek the lifeblood elementals.\n\nUse this gem on their remains to recover their rampant energy.  We'll need the energy to heal the land when all this is over.", sourceObjective = "The Avatar of Freya wants you to go to the Sundered Shard to the southeast and use the Lifeforce Gem on 8 destroyed Lifeblood Elementals.", progress = "Have you recovered the elementals' energy, {name}?", completion = "I thank you, {name}.  It is a shame that the pillar has fallen, but we must salvage what we can.", sourceObjectiveStatus = "unverified-source-field" }
quests[12806] = { id = 12806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Rise with all Due Haste!", description = "Some would say that our most critical mission lies not with the Lich King, but with the utter destruction of the Scarlet Onslaught. I would say that is foolish, but who am I to judge?\n\nDeath's Rise is far to the southwest, overlooking the sea along the cliff wall. There you will find Lord-Commander Arete personally overseeing the Onslaught's destruction himself.\n\n<The baron clears his throat.>\n\nDo see to it that you report to him with all due haste. He asked for you personally.", sourceObjective = "Report to Lord-Commander Arete at Death's Rise in Icecrown.", completion = "It's about damned time! No doubt that Baron Sliver took his sweet time in sending you to me.\n\nI should have that empty space above his shoulders removed!", sourceObjectiveStatus = "unverified-source-field" }
quests[12807] = { id = 12807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Story Thus Far...", description = "We have much to do, but first I believe a short refresher is in order.\n\nWe death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest.\n\nWhen you are ready for an earful, speak with me again and I shall provide enlightenment.", sourceObjective = "Listen to Lord-Commander Arete's tale at Death's Rise.", progress = "I suppose you think that you're ready to continue? How could you be though... you haven't yet heard the entirety of my tale!", completion = "In their folly, the Argent Crusade has chosen to turn a blind eye upon the presence of the Scarlet Onslaught. We will not.\n\nWe do not care if they might assist in the battle against the Lich King. We do not believe them worthy of existence. We will be their end, once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[12808] = { id = 12808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", sourceObjective = "Speak with Bishop Lazaril in the new Alliance camp at the Terrace of Light in Shattrath.", completion = "Brother {race}, I am proud to stand with you during our days of need.  Bless you, and may the clever eyes of your race help find a path to our salvation..", sourceObjectiveStatus = "unverified-source-field" }
quests[12809] = { id = 12809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  High Tinker Mekkatorque in Tinkertown will be eager to make use of the artifact's power.", sourceObjective = "Bishop Lazaril wants you to bring the Light-infused Artifact to High Tinker Mekkatorque in Ironforge.", progress = "Hello, {name}!  Look at you!  I see you have grown precisely one-point-seven-three microspans since last I saw you.  The airs of Outland have had an effect on you, I am certain of it.", completion = "Inconceivably immaculate!  This device stores Light energy at levels beyond those of any source yet known!  Oh, the possible applications shiver my whiskers and curl my toes.  Ho ho!  The anti-nocturnal photo-dispersement geno-actuator I could build with this would turn dusk into dawn!  The Scourge won't know what hit them.  We'll destroy them all in one pull of a lever!", sourceObjectiveStatus = "unverified-source-field" }
quests[12810] = { id = 12810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Water", description = "The forces at Onslaught Harbor are heavily reinforced by gryphon riders. You need a mount that will enable you to put them down. But first, we need the components for the ritual that is going to make it all happen.\n\nA great deal of blood is necessary for the ritual to be undertaken.\n\n<The lord-commander points down and to the northwest.>\n\nThere is a readily available supply down there in the harbor... sharks. Do not return to me until you've filled this bladder with their blood.", sourceObjective = "Lord-Commander Arete at Death's Rise wants you to fill the Gore Bladder with the blood of 10 Ravenous Jaws.", progress = "It's not glamorous work, but it is necessary.\n\nNow why is it that we are talking again before you are done, {class}?", completion = "Well done. Take a moment to let the saltwater dry from your skin before we continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[12811] = { id = 12811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", sourceObjective = "Speak with Grand Apothecary Putress in the new apothecary camp at the Terrace of Light in Shattrath.", completion = "What a fine, robust specimen you are.  We have many experiments to perform and our stable of volunteers is nearly bankrupt.  Fresh blood is welcome blood indeed, and your primal blood could fuel hours of research.", sourceObjectiveStatus = "unverified-source-field" }
quests[12812] = { id = 12812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Thrall in Orgrimmar.", sourceObjective = "Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Karlov in Orgrimmar.", progress = "Salutations, {name}.  You come from Shattrath?  You have instructions from Grand Apothecary Putress?", completion = "Ah, very good.  The diseases this rotted head carries are deadly, but we must not shy from danger or from what we find distasteful.  Some day, {name}, you will learn that damnation is the path to salvation...", sourceObjectiveStatus = "unverified-source-field" }
quests[12813] = { id = 12813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Their Corpses, Rise!", description = "How kind... how generous our lord-commander is. Where he is flowers and sunshine, I am filled only with hatred.\n\nIt is not enough to end their miserable lives... I want them humiliated... debased!\n\nWhat could be more unspeakable than to be turned into that which you hate? To dedicate your existence to eradicating a thing, and then in the end to become it?\n\nHow sad.\n\nTake this tincture northwest to Onslaught Harbor. Apply it to their still corpses and watch what happens, but avoid the cathedral.", sourceObjective = "Setaal Darkmender at Death's Rise has given you the Darkmender's Tincture. Apply it to the corpses of 10 of any of the Scarlet Onslaught units found at Onslaught Harbor.", progress = "Surely you're not done so soon?", completion = "<The draenei death knight fixes you with a cold stare, her eyes dead as the grave. A sly grin creeps across her features.>\n\nI'll have more of the tincture prepared tomorrow. Until then, be well.", sourceObjectiveStatus = "unverified-source-field" }
quests[12814] = { id = 12814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Need a Gryphon", description = "What could be more fitting than to take one of their own gryphons to use against them? Go to Onslaught Harbor and take the reins to one of their gryphons from the dead clutches of its rider.\n\nReturn with the gryphon, delivering it to Uzo Deathcaller. He will see to its proper transformation and provide you with further instructions.", sourceObjective = "Deliver an Onslaught Gryphon to Uzo Deathcaller at Death's Rise.", progress = "What took so long? Are their gryphons slow? We'll have to do something about that!", completion = "Oh yeah this is gonna be good!\n\nStand back... I'm gonna call down the wrath of the blood ritual!", sourceObjectiveStatus = "unverified-source-field" }
quests[12815] = { id = 12815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Fly Zone", description = "Now that you got your bone gryphon, I wantcha to take it back down there everyday and make a no fly zone over Onslaught Harbor.\n\nI gotta admit, mon, I don't really care if you use the bone gryphon to kill them gryphon riders or not. But I'm guessin' that if you do, you'll find it much easier to get to 'em.\n\nBesides, it's got lots of neat tricks you can use.", sourceObjective = "Uzo Deathcaller at Death's Rise wants you to kill 10 Onslaught Gryphon Riders.", progress = "What you back so soon for? I know I can still see those Onslaught boys still flyin' around down there!", completion = "That's the spirit! And you know, I need this done every day that we're here.\n\nI hope you'll come back again tomorrow. Your bone gryphon will be waitin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[12816] = { id = 12816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Silvermoon", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Silvermoon from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", sourceObjective = "Collect three Dim Necrotic Stones from the Scourge outside Silvermoon and investigate the glowing runic circles near their encampment.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[12817] = { id = 12817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Scourge of Exodar", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Exodar from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", sourceObjective = "Collect three Dim Necrotic Stones from the Scourge outside the Exodar and investigate the glowing runic circles near their encampment. Then return to Lieutenant Kregor.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[12818] = { id = 12818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Up", description = "To the point... Ricket's asked me to put together some stronger land mines, but I'm running low on parts.\n\nJust west of town, you'll find the remains of our last rocket sled... Ricket got a little excited when she was fueling it, but I probably should have thought to not put the nozzle right over the exhaust. Live and learn, eh?\n\nThere should be a good stock of spare parts scattered around the destroyed sled... why don't you go ahead and chase off those scavengers and nab me some of that wreckage?", sourceObjective = "Jeer Sparksocket at K3 would like 10 pieces of Charred Wreckage.", progress = "We have to have something we can use to insulate our engines against this cold... think, Jeer, think!\n\nOh hey! Did you get some of that wreckage for me?", completion = "These will do nicely, thanks!\n\nDid you happen to see Dim out there? I sent him out a long while back and he never came back. I hope he's alright.\n\nSpeaking of which... I wonder where Janks is...", sourceObjectiveStatus = "unverified-source-field" }
quests[12819] = { id = 12819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Around the Corner", description = "Blast it! Where are my tools? I had them here just a moment ago.\n\nOh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out.\n\nOh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.", sourceObjective = "Jeer Sparksocket at K3 would like Sparksocket's Tools retrieved from his minefield.", progress = "If Janks were here, I could have just sent him on this errand. Oh... on second thought... I'm not sure I told him where the safe path is anyway.\n\nGood thing I have you resourceful adventure types around, eh?", completion = "Ha ha! These are them! Thank you kindly. I hope you didn't have too much trouble traversing the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[12820] = { id = 12820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delicate Touch", description = "I've been waiting an eternity for these mines! Well, a few days at least. What took him so long?\n\nHere's the low down, compadre... there's this nasty bunch of magnataur--you know, big, hairy, and extremely ugly--and they seem pretty keen on taking K3 for themselves.\n\nNot going to happen.\n\nWe've got some defenses set up in their path, northeast of here. Sadly, our laser turrets have pretty limited power supplies... that's where these mines come in! Get over there and blow them up good!", sourceObjective = "Ricket at K3 wants you to use Improved Land Mines at Garm's Bane to fend off 12 attackers from Garm. Both Garm Invaders and Snowblind Followers will count towards this goal.", completion = "So... here I sat, basking in the awesomeness that is me, and in the distance, I hear a pop! Then another! Then a dozen more! And a smile crept onto my face at the thought of all those magnataur and snobolds eagerly rushing to their own deaths.\n\nWas it glorious?", sourceObjectiveStatus = "unverified-source-field" }
quests[12821] = { id = 12821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cell Block Tango", description = "The sapper squad is ready. That means it's time for fun!\n\nThere's only one thing holding us up from our full-scale assault on Garm! I sent a runner to set a teleporter up behind him--successfully I might add--and he returned to get the power cell it needs to function. It isn't working yet... which means the power cell didn't get there.\n\nI need you to look just on the other side of Garm's Bane for the power cell. When you find it, bring it farther east to Garm's Rise and activate the teleporter.", sourceObjective = "Ricket at K3 would like you to locate the Transporter Power Cell and use it to activate the Transportation Pad at Garm's Rise.", progress = "Even magnataur should know not to mess with goblins!", completion = "Excellent!\n\n<A fierce grin creeps onto Ricket's face.>\n\nLet the destruction begin!", sourceObjectiveStatus = "unverified-source-field" }
quests[12822] = { id = 12822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know No Fear", description = "Now that we have the teleporter open, my plan is quite complex... it has several facets and will take impeccable coordination. And there are supplies to be gathered! And troops to recruit! Likely, weeks of hard labor as well!\n\nHahah, I had you going there for a moment, didn't I? You've got this, kid. Hop through the teleporter and take the fight to them! Our sappers will back you up... they won't have anywhere to run.", sourceObjective = "Ricket at K3 wants you to kill 6 Garm Watchers and 8 Snowblind Devotees.", progress = "Nothing strikes fear into the enemy quite like a goblin sapper!", completion = "Haha! That'll teach those brutes to waste our time. From this day forth, green skin will strike fear into the hearts of all magnataur!", sourceObjectiveStatus = "unverified-source-field" }
quests[12823] = { id = 12823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flawless Plan", description = "Hey there! Joining us for the assault I assume?\n\nI've got a special task for you... we're going to bring the whole cave down on their heads! Towards the back of their cave, you should find Frostgut's Altar.  Sneak up and plant this hardpacked explosive bundle somewhere close to it.\n\nOnce the charge is placed, stick around just long enough to make sure Frostgut bites it, then get out quickly! There's no knowing how long the cave will last once that thing goes off!", sourceObjective = "Gino at Garm's Rise wants you to plant the Hardpacked Explosive Bundle near Frostgut's Altar, kill Tormar Frostgut, and then escape the cave before it collapses on you.", progress = "That explosive bundle is my baby... it took me weeks to perfect it. WEEKS!\n\nThat's a long time... okay.", completion = "The whole mountain shook! Was it gorgeous? I bet it was! How could it not be?\n\nAnd the Inventor's League tells me all of my inventions just blow up. Darn right they do! Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[12824] = { id = 12824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolitionist Extraordinaire", description = "You've got some swift feet on you sonny! Thanks for lending a hand with those explosives... I've been waiting to give that invention a good test run for a while!\n\nGo ahead and tell Ricket we should be covered on the magnataur front now... my sappers will clean up any of the remaining baddies.\n\nThanks again!", sourceObjective = "Return to Ricket at K3.", completion = "You blew the whole place up? Way to go! I bet Gino got a kick out of that.\n\nWe really appreciate all of the help you've lent us, {name}. How 'bout a souvenir for your troubles?", sourceObjectiveStatus = "unverified-source-field" }
quests[12825] = { id = 12825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expressions of Gratitude", sourceObjective = "[PLACEHOLDER] Use mini-plane to kamakazi on the gnoll leader.", sourceObjectiveStatus = "unverified-source-field" }
